/* Question banks, road signs and glossaries. EXTRA = sourced questions added Nov 2026. */
var EXTRA = {"drive":[{"t":"Hazard perception","hz":true,"q":"You drive 50 km/h in a built-up area (bebouwde kom). 20 m ahead a ball rolls onto the road from between two parked cars.","o":["Brake","Release the accelerator","Do nothing"],"c":0,"e":"A child may run out after the ball, and at 20 m only braking gives you enough margin. Releasing the accelerator is too little this close.","source":"https://www.cbr.nl/nl/rijbewijs-halen/auto/theorie-examen-auto/onderwerpen-in-het-theorie-examen.htm","view":{"road":"town","parked":"both","items":[{"k":"ball","x":0.4,"d":20}]}},{"t":"Hazard perception","hz":true,"q":"You drive 80 km/h on a rural road, 40 m behind another car. Its brake lights come on and it slows down sharply.","o":["Brake","Release the accelerator","Do nothing"],"c":0,"e":"The gap is closing fast, so you must brake now. Releasing the accelerator alone would not stop you running into it.","source":"https://www.cbr.nl/nl/rijbewijs-halen/auto/theorie-examen-auto/onderwerpen-in-het-theorie-examen.htm","view":{"road":"rural","trees":1,"items":[{"k":"car","x":0,"d":40,"brake":1}]}},{"t":"Hazard perception","hz":true,"q":"You drive 50 km/h. 25 m ahead a pedestrian steps onto a zebra crossing.","o":["Brake","Release the accelerator","Do nothing"],"c":0,"e":"You must let pedestrians on a zebra cross, and at 25 m you need to brake to stop in time.","source":"https://www.government.nl/site/binaries/site-content/collections/documents/2024/02/09/road-traffic-signs-and-regulations-in-the-netherlands/Road+Traffic+Signs+and+Regulations+in+the+Netherlands.pdf#page=35","view":{"road":"town","items":[{"k":"zebra","d":25},{"k":"adult","x":0.9,"d":26.5}]}},{"t":"Hazard perception","hz":true,"q":"You drive 100 km/h on the motorway. 150 m ahead, traffic in all lanes has come to a standstill and cars have their hazard lights on.","o":["Brake","Release the accelerator","Do nothing"],"c":0,"e":"At 100 km/h, 150 m is used up in about 5 seconds, so you need to brake now. Waiting until you are closer is the trap.","source":"https://www.cbr.nl/nl/rijbewijs-halen/auto/theorie-examen-auto/onderwerpen-in-het-theorie-examen.htm","view":{"road":"motorway","trees":1,"items":[{"k":"car","x":0,"d":150,"hazard":1},{"k":"car","x":-3.5,"d":152,"hazard":1,"c":"dv-c3"},{"k":"car","x":-7,"d":149,"hazard":1,"c":"dv-c4"},{"k":"truck","x":0,"d":160},{"k":"car","x":-3.5,"d":160,"c":"dv-c5"}]}},{"t":"Hazard perception","hz":true,"q":"You drive 50 km/h in a built-up area. 30 m ahead a bus at a stop on your side signals left and starts to pull away.","o":["Brake","Release the accelerator","Do nothing"],"c":0,"e":"Inside a built-up area you must give a bus the opportunity to pull away from a stop. At 30 m this requires braking.","source":"https://www.anwb.nl/verkeer/veiligheid/verkeersregels/voorrang","view":{"road":"town","items":[{"k":"bay","d":30},{"k":"bus","x":3.1,"d":30,"blink":1}]}},{"t":"Hazard perception","hz":true,"q":"You drive 30 km/h in a residential street. 10 m ahead a young child on a bicycle rides out of a driveway onto the road without looking.","o":["Brake","Release the accelerator","Do nothing"],"c":0,"e":"This is an immediate hazard very close to you, so brake. Even at 30 km/h, releasing the accelerator is not enough at 10 m.","source":"https://www.cbr.nl/nl/rijbewijs-halen/auto/theorie-examen-auto/onderwerpen-in-het-theorie-examen.htm","view":{"road":"town","items":[{"k":"bike","x":1.6,"d":10,"side":-1}]}},{"t":"Hazard perception","hz":true,"q":"You drive 40 km/h towards an equal junction 25 m ahead. A car approaches from your right and will arrive at about the same time as you.","o":["Brake","Release the accelerator","Do nothing"],"c":0,"e":"At an equal junction traffic from the right goes first, so you must slow down enough to let it pass. Releasing the accelerator will not do that in 25 m.","source":"https://www.government.nl/site/binaries/site-content/collections/documents/2024/02/09/road-traffic-signs-and-regulations-in-the-netherlands/Road+Traffic+Signs+and+Regulations+in+the+Netherlands.pdf#page=25","view":{"road":"town","items":[{"k":"side","d":25},{"k":"side","d":25,"side":-1},{"k":"car","x":6.5,"d":24,"side":-1}]}},{"t":"Hazard perception","hz":true,"q":"You drive 50 km/h in a built-up area. 50 m ahead, children are playing with a ball on the pavement close to the road.","o":["Brake","Release the accelerator","Do nothing"],"c":1,"e":"There is a possible hazard but nobody is on the road yet, so releasing the accelerator prepares you. Braking is not needed at this distance.","source":"https://www.cbr.nl/nl/rijbewijs-halen/auto/theorie-examen-auto/onderwerpen-in-het-theorie-examen.htm","view":{"road":"town","items":[{"k":"child","x":3,"d":50},{"k":"child","x":4,"d":52},{"k":"ball","x":2.3,"d":51}]}},{"t":"Hazard perception","hz":true,"q":"You drive 50 km/h towards an equal junction 60 m ahead. A tall hedge on the right blocks your view of the side road.","o":["Brake","Release the accelerator","Do nothing"],"c":1,"e":"Traffic from the right may appear and has priority, so release the accelerator to be ready to stop. Nothing is visible yet, so braking is not needed.","source":"https://www.cbr.nl/nl/rijbewijs-halen/auto/theorie-examen-auto/onderwerpen-in-het-theorie-examen.htm","view":{"road":"town","items":[{"k":"side","d":60},{"k":"hedge","x":2.2,"d1":26,"d2":57}]}},{"t":"Hazard perception","hz":true,"q":"You drive 100 km/h in the right lane of the motorway. 150 m ahead a car on the on-ramp is about to merge, and the lane to your left is busy.","o":["Brake","Release the accelerator","Do nothing"],"c":1,"e":"You cannot move over, so release the accelerator to give the merging car room. Braking on the motorway is not needed this far away.","source":"https://www.cbr.nl/nl/rijbewijs-halen/auto/theorie-examen-auto/onderwerpen-in-het-theorie-examen.htm","view":{"road":"motorway","ramp":150,"items":[{"k":"car","x":3.5,"d":150,"c":"dv-c3"},{"k":"car","x":-3.5,"d":35},{"k":"car","x":-3.5,"d":85,"c":"dv-c4"},{"k":"car","x":-7,"d":60,"c":"dv-c5"}]}},{"t":"Hazard perception","hz":true,"q":"You drive 80 km/h on a rural road. 100 m ahead a warning sign shows a sharp bend to the right and you cannot see beyond it.","o":["Brake","Release the accelerator","Do nothing"],"c":1,"e":"You must be able to stop within the distance you can see, so reduce speed before the bend by releasing the accelerator. There is no direct danger requiring braking.","source":"https://www.government.nl/site/binaries/site-content/collections/documents/2024/02/09/road-traffic-signs-and-regulations-in-the-netherlands/Road+Traffic+Signs+and+Regulations+in+the+Netherlands.pdf#page=26","view":{"road":"rural","items":[{"k":"bend","x":2.5,"d":100},{"k":"tree","x":4,"d":140,"h":9},{"k":"tree","x":-2,"d":175,"h":11},{"k":"tree","x":1.5,"d":170,"h":11},{"k":"tree","x":-6.5,"d":165,"h":10},{"k":"tree","x":6,"d":180,"h":10},{"k":"tree","x":-9,"d":120,"h":9}]}},{"t":"Hazard perception","hz":true,"q":"You drive 50 km/h. 60 m ahead a bus has stopped at a stop on your side and passengers are getting off.","o":["Brake","Release the accelerator","Do nothing"],"c":1,"e":"Passengers may cross the road in front of the bus, so release the accelerator. Nobody is on the road yet, so braking is too much.","source":"https://www.cbr.nl/nl/rijbewijs-halen/auto/theorie-examen-auto/onderwerpen-in-het-theorie-examen.htm","view":{"road":"town","items":[{"k":"bay","d":60},{"k":"bus","x":3.1,"d":60},{"k":"adult","x":5.3,"d":62},{"k":"adult","x":5.0,"d":65,"c":"dv-kid"}]}},{"t":"Hazard perception","hz":true,"q":"You drive 50 km/h. 50 m ahead a cyclist on the road looks back over his left shoulder, as if about to turn left.","o":["Brake","Release the accelerator","Do nothing"],"c":1,"e":"Looking back is a sign the cyclist may move across, so release the accelerator and be ready. He has not moved out yet, so braking is not needed.","source":"https://www.cbr.nl/nl/rijbewijs-halen/auto/theorie-examen-auto/onderwerpen-in-het-theorie-examen.htm","view":{"road":"town","items":[{"k":"bike","x":0.3,"d":50,"look":1}]}},{"t":"Hazard perception","hz":true,"q":"You drive 80 km/h on a rural road. 150 m ahead a slow tractor drives in your lane and constant oncoming traffic means you cannot overtake.","o":["Brake","Release the accelerator","Do nothing"],"c":1,"e":"You will catch up with the tractor and cannot pass it, so release the accelerator early. At 150 m there is no need to brake.","source":"https://www.cbr.nl/nl/rijbewijs-halen/auto/theorie-examen-auto/onderwerpen-in-het-theorie-examen.htm","view":{"road":"rural","trees":1,"items":[{"k":"tractor","x":0,"d":150,"rear":1},{"k":"car","x":-3.2,"d":60,"front":1},{"k":"car","x":-3.2,"d":120,"front":1,"c":"dv-c4"},{"k":"car","x":-3.2,"d":200,"front":1,"c":"dv-c3"}]}},{"t":"Hazard perception","hz":true,"q":"You drive 100 km/h on a dry motorway with light traffic. The car in front is 80 m ahead and drives at the same speed.","o":["Brake","Release the accelerator","Do nothing"],"c":2,"e":"An 80 m gap at 100 km/h is almost 3 seconds, more than the 2-second rule. There is no hazard, so you do not need to change anything.","source":"https://www.anwb.nl/verkeer/veiligheid/verkeersregels/afstand-houden","view":{"road":"motorway","trees":1,"items":[{"k":"car","x":0,"d":80,"c":"dv-c3"}]}},{"t":"Hazard perception","hz":true,"q":"You drive 50 km/h on a priority road. 40 m ahead, a car has stopped at the shark teeth (haaientanden) of a side road on your right and is waiting.","o":["Brake","Release the accelerator","Do nothing"],"c":2,"e":"The car has stopped and must give way to you, so there is no reason to slow down. Releasing the accelerator here only confuses other traffic.","source":"https://www.anwb.nl/verkeer/veiligheid/verkeersregels/voorrang","view":{"road":"town","items":[{"k":"side","d":40,"teeth":1},{"k":"car","x":6.3,"d":38,"side":-1}]}},{"t":"Hazard perception","hz":true,"q":"You drive 80 km/h on a rural road. Cyclists ride on a separate cycle track, divided from the road by a wide ditch.","o":["Brake","Release the accelerator","Do nothing"],"c":2,"e":"The cyclists cannot reach your road, so there is no hazard and you keep your speed.","source":"https://www.cbr.nl/nl/rijbewijs-halen/auto/theorie-examen-auto/onderwerpen-in-het-theorie-examen.htm","view":{"road":"rural","ditch":1,"items":[{"k":"bike","x":8,"d":30},{"k":"bike","x":8.4,"d":60}]}},{"t":"Hazard perception","hz":true,"q":"You drive 50 km/h. The traffic light 100 m ahead has just turned green and there are no other road users around.","o":["Brake","Release the accelerator","Do nothing"],"c":2,"e":"The light has only just turned green and is far away, with no other traffic. There is nothing to react to.","source":"https://www.cbr.nl/nl/rijbewijs-halen/auto/theorie-examen-auto/onderwerpen-in-het-theorie-examen.htm","view":{"road":"town","items":[{"k":"side","d":100},{"k":"side","d":100,"side":-1},{"k":"light","x":2.4,"d":96,"color":"green"}]}},{"t":"Hazard perception","hz":true,"q":"You drive 80 km/h on a straight rural road with good visibility. An oncoming car is 200 m away, in its own lane.","o":["Brake","Release the accelerator","Do nothing"],"c":2,"e":"Oncoming traffic that stays in its own lane is normal and is no hazard. No action is needed.","source":"https://www.cbr.nl/nl/rijbewijs-halen/auto/theorie-examen-auto/onderwerpen-in-het-theorie-examen.htm","view":{"road":"rural","trees":1,"items":[{"k":"car","x":-3.2,"d":200,"front":1}]}},{"t":"Hazard perception","hz":true,"q":"You drive 100 km/h on the motorway. A faster car overtakes you and moves back into your lane 70 m ahead, pulling further away.","o":["Brake","Release the accelerator","Do nothing"],"c":2,"e":"The gap is growing because the other car is faster, so there is nothing to do. Braking here could surprise the traffic behind you.","source":"https://www.cbr.nl/nl/rijbewijs-halen/auto/theorie-examen-auto/onderwerpen-in-het-theorie-examen.htm","view":{"road":"motorway","trees":1,"items":[{"k":"car","x":0,"d":70}]}},{"t":"Priority","q":"At an equal junction (no signs or markings) you go straight on. A city bus approaches from your right and also goes straight on. Who goes first?","o":["You, because buses never get priority at junctions","The bus, because public transport always has priority","The bus, because it comes from your right","You, because you reached the junction first"],"c":2,"e":"Right-first applies to every driver at an equal junction, bus drivers included. Unlike trams, buses have no general priority.","source":"https://www.government.nl/site/binaries/site-content/collections/documents/2024/02/09/road-traffic-signs-and-regulations-in-the-netherlands/Road+Traffic+Signs+and+Regulations+in+the+Netherlands.pdf#page=25","map":{"g":"cross","items":[{"at":"S","you":1,"go":"straight"},{"at":"E","k":"bus","x":170,"go":"straight","lbl":"Bus"}]}},{"t":"Priority","q":"At an equal junction a funeral procession approaches from your left. The cars carry black flags with white stripes. What do you do?","o":["Let the procession pass without cutting in","Go first, because the procession comes from your left","Let the hearse pass, then join between the cars","Go first after sounding your horn briefly"],"c":0,"e":"At an equal junction you must give way to the cars of a funeral procession, even from the left, and you may not cut through it. Right-first does not help you here.","source":"https://www.government.nl/site/binaries/site-content/collections/documents/2024/02/09/road-traffic-signs-and-regulations-in-the-netherlands/Road+Traffic+Signs+and+Regulations+in+the+Netherlands.pdf#page=25","map":{"g":"cross","items":[{"at":"S","you":1,"go":"straight"},{"at":"W","c":"c-dark","go":"straight","lbl":"Funeral"},{"x":4,"y":115,"r":90,"c":"c-dark"}]}},{"t":"Priority","q":"You are driving on a roundabout. A funeral procession wants to enter it from a road with shark teeth. Who goes first?","o":["The procession, because it always has priority","The procession, because it comes from your right","Whoever reaches the entry point first","You, because a procession has no priority here"],"c":3,"e":"A funeral procession has priority at equal junctions, but not at roundabouts, priority roads or traffic lights. Here the shark teeth apply to the procession too.","source":"https://www.anwb.nl/verkeer/veiligheid/verkeersregels/rouwstoet","map":{"g":"round","teeth":["S"],"items":[{"at":"S","you":1,"x":68,"y":100,"r":180,"path":"M71.7 115A32 32 0 0 0 128 116"},{"x":115,"y":172,"r":0,"c":"c-dark","lbl":"Funeral"},{"x":115,"y":204,"r":0,"c":"c-dark"}]}},{"t":"Priority","q":"Inside a built-up area (bebouwde kom), a bus at a stop just ahead of you signals left to pull away. What must you do?","o":["Overtake quickly before the bus moves","Give the bus the opportunity to pull away","Drive on, as the bus makes a special manoeuvre","Sound your horn to warn the bus driver"],"c":1,"e":"Inside built-up areas you must let a bus that signals pull away from its stop. Outside built-up areas this rule does not apply.","source":"https://www.government.nl/site/binaries/site-content/collections/documents/2024/02/09/road-traffic-signs-and-regulations-in-the-netherlands/Road+Traffic+Signs+and+Regulations+in+the+Netherlands.pdf#page=37","map":{"g":"road","stop":1,"note":"Built-up area","items":[{"k":"bus","x":148,"y":92,"r":0,"blink":"left","path":"M148 66Q148 50 122 38V18"},{"at":"S","you":1,"x":120,"y":175,"r":0,"go":"straight"}]}},{"t":"Priority","q":"Outside a built-up area a bus at a stop signals that it wants to pull away. Who goes first?","o":["The bus, as a bus leaving a stop goes first","You; outside built-up areas the bus waits","The bus, if it runs a scheduled service","You, but only if you are on a priority road"],"c":1,"e":"Outside built-up areas pulling away from a stop is a normal special manoeuvre, so the bus must wait for other traffic. The rule that lets buses go is only for inside built-up areas.","source":"https://www.government.nl/site/binaries/site-content/collections/documents/2024/02/09/road-traffic-signs-and-regulations-in-the-netherlands/Road+Traffic+Signs+and+Regulations+in+the+Netherlands.pdf#page=37","map":{"g":"road","stop":1,"note":"Outside built-up area","items":[{"k":"bus","x":148,"y":92,"r":0,"blink":"left","path":"M148 66Q148 50 122 38V18"},{"at":"S","you":1,"x":120,"y":175,"r":0,"go":"straight"}]}},{"t":"Priority","q":"Which signals make a police car a priority vehicle (voorrangsvoertuig) that you must give way to?","o":["Blue flashing lights on their own","Flashing headlights plus hazard lights","A two-tone horn without any lights","Blue lights plus a two-tone horn"],"c":3,"e":"A priority vehicle uses blue flashing lights together with a two-tone horn. Blue lights alone do not make it a priority vehicle.","source":"https://www.government.nl/site/binaries/site-content/collections/documents/2024/02/09/road-traffic-signs-and-regulations-in-the-netherlands/Road+Traffic+Signs+and+Regulations+in+the+Netherlands.pdf#page=30"},{"t":"Priority","q":"You pull away from a parking space at the same moment as a driver opposite starts a U-turn. Who has priority?","o":["No fixed order; settle it between you","The U-turning driver, as turning ranks higher","You, because you were stationary first","You, because the other driver comes from your left"],"c":0,"e":"Both of you are making a special manoeuvre, and there is no order of priority between special manoeuvres. Right-first does not decide it.","source":"https://www.anwb.nl/verkeer/veiligheid/verkeersregels/voorrang","map":{"g":"road","park":"both","items":[{"at":"S","you":1,"x":152,"y":120,"r":0,"path":"M152 102Q152 84 122 72V40"},{"x":48,"y":80,"r":180,"path":"M48 98Q52 128 80 130Q116 128 120 96"}]}},{"t":"Priority","q":"You are reversing along a street to reach a parking space. A cyclist approaches from behind you. Who goes first?","o":["You, because you signalled your intention first","You, because cyclists must give way to cars","The cyclist; reversing is a special manoeuvre","The cyclist, but only when coming from your right"],"c":2,"e":"Reversing is a special manoeuvre, so you must let all other traffic go first. Direction does not matter.","source":"https://www.government.nl/site/binaries/site-content/collections/documents/2024/02/09/road-traffic-signs-and-regulations-in-the-netherlands/Road+Traffic+Signs+and+Regulations+in+the+Netherlands.pdf#page=36","map":{"g":"road","park":"right","items":[{"at":"S","you":1,"x":120,"y":80,"r":0,"path":"M120 98V114Q122 130 150 142"},{"k":"bike","x":128,"y":182,"r":0,"path":"M128 168V120"}]}},{"t":"Priority","q":"You make a U-turn on a two-way road. Whom must you give way to?","o":["Only traffic from your right","Only oncoming traffic","All other traffic","Only traffic behind you"],"c":2,"e":"A U-turn is a special manoeuvre, so you give way to all other traffic, from every direction.","source":"https://www.government.nl/site/binaries/site-content/collections/documents/2024/02/09/road-traffic-signs-and-regulations-in-the-netherlands/Road+Traffic+Signs+and+Regulations+in+the+Netherlands.pdf#page=36","map":{"g":"road","items":[{"at":"S","you":1,"x":120,"y":135,"r":0,"go":"uturn"},{"x":80,"y":30,"r":180,"path":"M80 50V70"},{"x":120,"y":192,"r":0}]}},{"t":"Priority","q":"On a road with two lanes in your direction, you move from the right lane to the left lane. A car in the left lane is just behind you. Who goes first?","o":["The car already in the left lane","You, because you are ahead of it","You, if you signal in good time","Whoever is driving faster"],"c":0,"e":"Changing lanes is a special manoeuvre, so you give way to traffic already in the lane you want to enter. Signalling does not give you priority.","source":"https://www.government.nl/site/binaries/site-content/collections/documents/2024/02/09/road-traffic-signs-and-regulations-in-the-netherlands/Road+Traffic+Signs+and+Regulations+in+the+Netherlands.pdf#page=36","map":{"g":"lanes","items":[{"at":"S","you":1,"x":120,"y":95,"r":0,"path":"M120 77V64Q120 44 82 24"},{"x":80,"y":150,"r":0,"path":"M80 130V100"}]}},{"t":"Priority","q":"On the motorway you move from the main carriageway into the exit lane (uitvoegstrook). A car is already in the exit lane next to you. Who has priority?","o":["You, because you signalled first","You, as main-carriageway traffic ranks higher","Whoever reaches the end of the lane first","The car already in the exit lane"],"c":3,"e":"Moving from the main carriageway to the exit lane is a special manoeuvre. You give way to traffic already in that lane.","source":"https://www.government.nl/site/binaries/site-content/collections/documents/2024/02/09/road-traffic-signs-and-regulations-in-the-netherlands/Road+Traffic+Signs+and+Regulations+in+the+Netherlands.pdf#page=36","map":{"g":"exit","items":[{"at":"S","you":1,"x":130,"y":125,"r":0,"path":"M130 107V96Q132 78 160 60"},{"x":164,"y":100,"r":0,"path":"M164 82V40"}]}},{"t":"Priority","q":"You approach a roundabout with shark teeth and a triangular give-way sign on your road. A car on the roundabout comes from your left. Who goes first?","o":["You, because the car comes from your left","The car on the roundabout","You, because entering traffic goes first","Whoever is the larger vehicle"],"c":1,"e":"Shark teeth and the give-way sign mean you give way to traffic on the roundabout. Right-first does not apply here.","source":"https://www.anwb.nl/verkeer/veiligheid/verkeersregels/voorrang","map":{"g":"round","teeth":["S"],"signs":[["S","give-way"]],"items":[{"at":"S","you":1,"x":115,"y":176,"r":0,"path":"M115 154V138Q118 128 128 118"},{"x":77,"y":123,"r":135,"path":"M88 131A32 32 0 0 0 128 116"}]}},{"t":"Priority","q":"You are driving on a small roundabout without any signs or shark teeth. A car wants to enter from a road on your right. Who goes first?","o":["You, because roundabout traffic always has priority","The entering car, because right-first applies","You, because the entering car must stop","The entering car, because it is larger"],"c":1,"e":"Without signs or markings, the general rule applies: traffic from the right goes first, even at a roundabout. Many drivers wrongly think roundabout traffic always has priority.","source":"https://www.government.nl/site/binaries/site-content/collections/documents/2024/02/09/road-traffic-signs-and-regulations-in-the-netherlands/Road+Traffic+Signs+and+Regulations+in+the+Netherlands.pdf#page=25","map":{"g":"round","items":[{"at":"S","you":1,"x":77,"y":123,"r":135,"path":"M88 131A32 32 0 0 0 128 116"},{"x":115,"y":176,"r":0,"path":"M115 154V138Q118 128 128 118"}]}},{"t":"Priority","q":"Inside a built-up area you leave a roundabout. The cycle track around it crosses your exit, and shark teeth are painted on your road before that crossing. A cyclist is about to cross. Who goes first?","o":["You, because cyclists on roundabouts never have priority","You, because you are leaving the roundabout","The cyclist, but only if coming from your right","The cyclist, because the shark teeth are on your side"],"c":3,"e":"The shark teeth on your road mean you must give way to the cyclist on the cycle track. Leaving a roundabout gives you no priority.","source":"https://www.anwb.nl/verkeer/veiligheid/verkeersregels/voorrang","map":{"g":"round","cycle":1,"note":"Built-up area","tline":[[73,150,98,150,-1]],"items":[{"at":"S","you":1,"x":85,"y":134,"r":180,"path":"M85 152V190"},{"k":"bike","x":58,"y":152,"r":125,"path":"M66 158A66 66 0 0 0 112 165"}]}},{"t":"Priority","q":"Outside a built-up area you approach a roundabout. Cyclists on the separate cycle track have shark teeth and a give-way sign before they cross your road; you have none at that crossing. Who goes first?","o":["You; the shark teeth are on the cycle track","The cyclist; cyclists always go first at roundabouts","The cyclist, because they come from your right","You, because cars outside built-up areas go first"],"c":0,"e":"The road markings decide: the shark teeth on the cycle track mean the cyclist gives way. Cyclists have no automatic priority at roundabouts.","source":"https://www.anwb.nl/verkeer/veiligheid/verkeersregels/voorrang","map":{"g":"round","cycle":1,"note":"Outside built-up area","tline":[[64,152,64,172,1]],"items":[{"at":"S","you":1,"x":115,"y":186,"r":0,"path":"M115 168V150"},{"k":"bike","x":46,"y":138,"r":140,"path":"M52 146A66 66 0 0 0 112 165"}]}},{"t":"Priority","q":"A pedestrian is standing at the kerb next to a zebra crossing, clearly waiting to cross. Nobody is on the crossing yet. What must you do?","o":["Drive on, since nobody is on the crossing yet","Drive on unless the pedestrian raises a hand","Stop and let the pedestrian cross","Sound your horn and continue slowly"],"c":2,"e":"You must give way to pedestrians who are crossing or clearly waiting to cross at a zebra. You may not wait until they step onto it.","source":"https://www.government.nl/site/binaries/site-content/collections/documents/2024/02/09/road-traffic-signs-and-regulations-in-the-netherlands/Road+Traffic+Signs+and+Regulations+in+the+Netherlands.pdf#page=35","map":{"g":"road","zebra":[74],"items":[{"k":"ped","x":150,"y":82},{"at":"S","you":1,"x":120,"y":168,"r":0,"go":"straight"}]}},{"t":"Priority","q":"At a zebra crossing with traffic lights, the pedestrian light shows red and your light shows green. A pedestrian is waiting at the kerb. Who goes first?","o":["The pedestrian, because a zebra always gives priority","The pedestrian, because they were there first","You, as pedestrians have no priority on red","You, but only after sounding your horn"],"c":2,"e":"When a red pedestrian light stops pedestrians from crossing, they lose their zebra priority. The lights decide here.","source":"https://www.government.nl/site/binaries/site-content/collections/documents/2024/02/09/road-traffic-signs-and-regulations-in-the-netherlands/Road+Traffic+Signs+and+Regulations+in+the+Netherlands.pdf#page=36","map":{"g":"road","zebra":[74],"lights":[[150,124,"green"]],"plights":[[160,60,"red"]],"items":[{"k":"ped","x":150,"y":82},{"at":"S","you":1,"x":120,"y":168,"r":0,"go":"straight"}]}},{"t":"Priority","q":"A tram has stopped in the middle of the road at a stop without a platform. Passengers are getting off on your side. What must you do?","o":["Give way to the passengers","Overtake the tram on its left side","Pass slowly while sounding your horn","Pass, as the passengers must wait for you"],"c":0,"e":"When you pass a stationary tram or bus on the side where passengers get on and off, you must give way to them.","source":"https://www.government.nl/site/binaries/site-content/collections/documents/2024/02/09/road-traffic-signs-and-regulations-in-the-netherlands/Road+Traffic+Signs+and+Regulations+in+the+Netherlands.pdf#page=36","map":{"g":"road","rails":1,"items":[{"k":"tram","x":100,"y":70,"r":0,"lbl":"Tram"},{"k":"ped","x":118,"y":66,"path":"M118 66H136"},{"k":"ped","x":122,"y":86},{"at":"S","you":1,"x":122,"y":175,"r":0,"go":"straight"}]}},{"t":"Priority","q":"At a junction you want to turn left. An oncoming car wants to turn right into the same street. Who goes first?","o":["You, because you were at the junction first","Whoever signalled first","You, because left turns get priority","The oncoming car turning right"],"c":3,"e":"A driver turning left must give way to an oncoming driver turning right at the same junction.","source":"https://www.government.nl/site/binaries/site-content/collections/documents/2024/02/09/road-traffic-signs-and-regulations-in-the-netherlands/Road+Traffic+Signs+and+Regulations+in+the+Netherlands.pdf#page=26","map":{"g":"cross","items":[{"at":"S","you":1,"go":"left"},{"at":"N","go":"right"}]}},{"t":"Priority","q":"A tram approaches a zebra crossing where a pedestrian is crossing. What must the tram driver do?","o":["Continue, as trams always have priority","Let the pedestrian cross","Ring the bell and continue","Continue if the pedestrian is not halfway yet"],"c":1,"e":"Trams have priority over other drivers, but tram drivers must still obey signs and lights and let pedestrians cross at a zebra.","source":"https://www.government.nl/site/binaries/site-content/collections/documents/2024/02/09/road-traffic-signs-and-regulations-in-the-netherlands/Road+Traffic+Signs+and+Regulations+in+the+Netherlands.pdf#page=35","map":{"g":"road","rails":1,"zebra":[72],"items":[{"k":"ped","x":122,"y":80,"path":"M122 80H76"},{"k":"tram","x":100,"y":150,"r":0,"lbl":"Tram"}]}},{"t":"Priority","q":"A military column of motor vehicles is driving through a junction you want to cross. What must you do?","o":["Cut through at a gap between two vehicles","Wait; you may not cut through the column","Cross, because you come from the right","Flash your headlights and then cross"],"c":1,"e":"Road users may not cut through military columns or motorised funeral processions. Right-first does not change that.","source":"https://www.government.nl/site/binaries/site-content/collections/documents/2024/02/09/road-traffic-signs-and-regulations-in-the-netherlands/Road+Traffic+Signs+and+Regulations+in+the+Netherlands.pdf#page=25","map":{"g":"cross","items":[{"at":"S","you":1,"go":"straight"},{"at":"W","k":"truck","c":"c-army","x":44,"go":"straight","lbl":"Army"},{"k":"truck","c":"c-army","x":0,"y":115,"r":90}]}},{"t":"Priority","q":"Your traffic light turns green, but traffic beyond the junction is queuing. If you drive on, you will have to stop on the junction. What do you do?","o":["Drive onto the junction; your light is green","Drive onto the junction with hazard lights on","Drive up halfway and wait there","Wait before the junction until there is room"],"c":3,"e":"Drivers must not block a junction, even with a green light. Wait until there is space beyond it.","source":"https://www.government.nl/site/binaries/site-content/collections/documents/2024/02/09/road-traffic-signs-and-regulations-in-the-netherlands/Road+Traffic+Signs+and+Regulations+in+the+Netherlands.pdf#page=25","map":{"g":"cross","lights":[["S","green"]],"items":[{"at":"S","you":1},{"x":115,"y":48,"r":0},{"x":115,"y":14,"r":0}]}},{"t":"Priority","q":"In a 30 km/h zone you reach a junction without signs or markings. A car approaches from your right. Who goes first?","o":["The car from the right; normal rules apply","You, because main traffic goes first in 30 zones","Whoever is going straight on","You, because 30 zones have no priority rules"],"c":0,"e":"In a woonerf or 30 km/h zone the normal priority rules apply, so traffic from the right goes first.","source":"https://www.government.nl/site/binaries/site-content/collections/documents/2024/02/09/road-traffic-signs-and-regulations-in-the-netherlands/Road+Traffic+Signs+and+Regulations+in+the+Netherlands.pdf#page=25","map":{"g":"cross","note":"30 km/h zone","items":[{"at":"S","you":1,"go":"straight"},{"at":"E","go":"straight"}]}},{"t":"Priority","q":"In a 30 km/h zone you leave a side street that joins the road through a raised kerb and pavement crossing (uitritconstructie). A cyclist approaches from your left. Who goes first?","o":["You, because the cyclist comes from your left","You, because a car outranks a cyclist","The cyclist, as you are leaving an exit","The cyclist, because cyclists always have priority"],"c":2,"e":"An exit construction with a height difference counts as leaving an exit, so you give way to all road users. Right-first does not apply.","source":"https://www.government.nl/site/binaries/site-content/collections/documents/2024/02/09/road-traffic-signs-and-regulations-in-the-netherlands/Road+Traffic+Signs+and+Regulations+in+the+Netherlands.pdf#page=36","map":{"g":"tee","from":"exit","note":"Exit over the pavement","items":[{"at":"S","you":1,"x":115,"y":168,"go":"right"},{"at":"W","k":"bike","go":"straight"}]}},{"t":"Priority","q":"There is no sign at a junction, but shark teeth (haaientanden) are painted across your lane. A car approaches from your left. Who goes first?","o":["You, as markings without a sign do not count","You, because the car comes from your left","The car from the left","Whoever reaches the junction first"],"c":2,"e":"Shark teeth on their own mean you must give way to traffic on the crossing road, from both directions.","source":"https://www.anwb.nl/verkeer/veiligheid/verkeersregels/voorrang","map":{"g":"cross","teeth":["S"],"items":[{"at":"S","you":1,"go":"straight"},{"at":"W","go":"straight"}]}},{"t":"Signs","q":"A square blue sign with a white number (for example 70) means:","o":["Advisory speed","Minimum speed","Maximum speed","End of maximum speed"],"c":0,"e":"A blue square with a number (A4) is an advisory speed. A maximum speed is shown on a round sign with a red border (A1).","source":"https://www.anwb.nl/verkeer/nederland/verkeersinformatie/verkeersborden-nederland"},{"t":"Signs","q":"A round blue sign with a white bicycle (G11) means:","o":["Recommended cycle route; cars are allowed","Bicycle street where cars are also allowed","Cyclists have priority at the next junction","Mandatory cycle path; cars may not use it"],"c":3,"e":"A round blue sign with a bicycle marks a mandatory cycle path. A bicycle street (fietsstraat) has a rectangular sign.","source":"https://www.anwb.nl/verkeer/nederland/verkeersinformatie/verkeersborden-nederland"},{"t":"Signs","q":"A rectangular blue sign with the word 'fietspad' (G13) means:","o":["Mandatory cycle path for all two-wheelers","Optional cycle path, not mandatory","Cycle path with priority over side roads","Closed to all motor vehicles including cars"],"c":1,"e":"The rectangular 'fietspad' sign marks an optional cycle path. The round blue bicycle sign is the mandatory one.","source":"https://www.anwb.nl/verkeer/nederland/verkeersinformatie/verkeersborden-nederland"},{"t":"Signs","q":"A round white sign with a red border showing a black car (C6) means:","o":["Closed to every motor vehicle, motorcycles included","Closed to motor vehicles with more than two wheels","No overtaking of motor vehicles on this road","No parking for cars along this side of the road"],"c":1,"e":"C6 closes the road to motor vehicles with more than two wheels, such as cars. Motorcycles are not included; that needs a different sign.","source":"https://www.anwb.nl/verkeer/nederland/verkeersinformatie/verkeersborden-nederland"},{"t":"Signs","q":"A round blue sign with a red border and one red diagonal stripe (E1) means:","o":["No stopping, not even briefly","No entry for vehicles from this side","End of all previous prohibitions","No parking; brief stops are allowed"],"c":3,"e":"E1 is a parking ban: you may still stop to let passengers in or out or to load goods. The sign with a red cross (E2) bans stopping.","source":"https://www.anwb.nl/verkeer/nederland/verkeersinformatie/verkeersborden-nederland"},{"t":"Signs","q":"A round blue sign with a red border and a red cross (E2) means:","o":["No stopping on this side","No parking, but loading is allowed","Crossroads with priority ahead","Road closed in both directions"],"c":0,"e":"The red cross on a blue background bans stopping as well as parking on that side of the road.","source":"https://www.anwb.nl/verkeer/nederland/verkeersinformatie/verkeersborden-nederland"},{"t":"Signs","q":"Outside a built-up area, where is the priority road sign (yellow diamond, B1) placed at a junction?","o":["Just before the junction","Only at the start of the road","Just after the junction","100 m before every junction"],"c":2,"e":"Outside built-up areas the B1 sign stands after the junction; inside built-up areas it stands just before it.","source":"https://www.anwb.nl/verkeer/veiligheid/verkeersregels/voorrang-buiten-de-bebouwde-kom"},{"t":"Signs","q":"A red-bordered warning triangle with a black crossroads symbol, in which the vertical road is drawn thicker (B3), means:","o":["You are on a priority road from here on","Dangerous crossroads; right-first applies","Priority at the next junction only","Give way at the next junction"],"c":2,"e":"B3 gives you priority at the next junction only. It does not make the whole road a priority road.","source":"https://www.anwb.nl/verkeer/nederland/verkeersinformatie/verkeersborden-nederland"},{"t":"Signs","q":"A rectangular blue sign showing a white cyclist with a red car behind it (L51) means:","o":["Bicycle street; cars are also allowed","Cycle path; cars are not allowed","Cars must overtake cyclists here","Car-free zone with bicycle parking"],"c":0,"e":"L51 marks a bicycle street (fietsstraat), where cars may drive but cyclists set the tone.","source":"https://www.anwb.nl/verkeer/nederland/verkeersinformatie/verkeersborden-nederland"},{"t":"Signs","q":"A round white sign with a red border showing a red car next to a black car (F1) means:","o":["No overtaking of any road user, cyclists included","Lorries may not overtake cars","Overtaking is allowed on the right only","Motor vehicles may not overtake each other"],"c":3,"e":"F1 bans overtaking between motor vehicles. You may still overtake a cyclist, and the lorry-only version is a different sign (F3).","source":"https://www.anwb.nl/verkeer/nederland/verkeersinformatie/verkeersborden-nederland"},{"t":"Signs","q":"A square blue sign with a white arrow pointing up and a red arrow pointing down (F6) means:","o":["You must give way to oncoming traffic","Oncoming traffic must give way to you","Two-way traffic ahead","One-way road ahead"],"c":1,"e":"On F6 the white arrow is your direction, so oncoming drivers must wait for you. The round sign with the arrows reversed (F5) means you must wait.","source":"https://www.anwb.nl/verkeer/nederland/verkeersinformatie/verkeersborden-nederland"},{"t":"Signs","q":"In a tunnel you see a long green sign with a white running figure and distances in metres (L19). What does it show?","o":["The distance to the end of the tunnel","Where the nearest emergency exit is","Where pedestrians may walk in the tunnel","The minimum following distance in the tunnel"],"c":1,"e":"L19 shows how far away the nearest emergency exit is and in which direction. Knowing this matters if there is a fire.","source":"https://www.anwb.nl/verkeer/nederland/verkeersinformatie/verkeersborden-nederland"},{"t":"Road markings","q":"In a parking disc zone (blauwe zone), a parking space is marked with a blue line. This means:","o":["Parking only for permit holders","No parking at any time","Parking only for electric cars","You may park there with a parking disc"],"c":3,"e":"In a disc zone you may park only in spaces with a blue line or marked bays, using a parking disc.","source":"https://www.government.nl/site/binaries/site-content/collections/documents/2024/02/09/road-traffic-signs-and-regulations-in-the-netherlands/Road+Traffic+Signs+and+Regulations+in+the+Netherlands.pdf#page=30"},{"t":"Road markings","q":"A peak-hour lane (spitsstrook) is separated from your lane by a solid line. The sign above shows the lane is open. May you cross the solid line to use it?","o":["Yes, crossing is allowed while it is open","No, a solid line may never be crossed","Only to overtake slower traffic","Only when a police officer signals"],"c":0,"e":"When the peak-hour lane is open you may cross the solid line to enter it. A solid line normally may not be crossed, but the law makes an exception for entering a hard shoulder or an open peak-hour lane.","source":"https://www.government.nl/site/binaries/site-content/collections/documents/2024/02/09/road-traffic-signs-and-regulations-in-the-netherlands/Road+Traffic+Signs+and+Regulations+in+the+Netherlands.pdf#page=46"},{"t":"Road markings","q":"A continuous white line runs along the middle of the road (not at the edge). What does it mean?","o":["You may cross it to overtake","You may cross it if the road is clear","You may not cross it","You may cross it only in built-up areas"],"c":2,"e":"A continuous line that is not along the edge of the carriageway may not be crossed.","source":"https://www.government.nl/site/binaries/site-content/collections/documents/2024/02/09/road-traffic-signs-and-regulations-in-the-netherlands/Road+Traffic+Signs+and+Regulations+in+the+Netherlands.pdf#page=46"},{"t":"Speed limits","q":"You pass a blue sign with a place name crossed through by a red line (H2). Unless other signs say otherwise, the maximum speed for cars is now:","o":["100 km/h","70 km/h","80 km/h","60 km/h"],"c":2,"e":"H2 marks the end of the built-up area, where 80 km/h applies on ordinary roads unless signs show otherwise.","source":"https://www.anwb.nl/verkeer/nederland/verkeersinformatie/verkeersborden-nederland"},{"t":"Speed limits","q":"A matrix sign above your lane shows 70. The roadside sign shows 100. What is your maximum speed?","o":["70 km/h","100 km/h","100 km/h, as matrix signs are only advice","70 km/h, but only for lorries"],"c":0,"e":"When a matrix sign shows a lower speed than the roadside sign, you must keep to the matrix sign.","source":"https://www.rijksoverheid.nl/vraag-en-antwoord/verkeersveiligheid/wat-is-de-maximumsnelheid-voor-auto-s-op-de-snelweg"},{"t":"Speed limits","q":"On a motorway after 19:00, where no sign shows a different limit, the legal maximum speed for cars is:","o":["100 km/h","120 km/h","110 km/h","130 km/h"],"c":3,"e":"The legal maximum on motorways is 130 km/h. The daytime 100 km/h limit is set by signs and applies from 06:00 to 19:00.","source":"https://www.government.nl/site/binaries/site-content/collections/documents/2024/02/09/road-traffic-signs-and-regulations-in-the-netherlands/Road+Traffic+Signs+and+Regulations+in+the+Netherlands.pdf#page=26"},{"t":"Speed limits","q":"You pass a blue sign with a place name (H1). Unless other signs say otherwise, the maximum speed for cars from that sign is:","o":["30 km/h","50 km/h","60 km/h","40 km/h"],"c":1,"e":"The place name sign marks the start of the built-up area, where 50 km/h applies for motor vehicles. A 30 km/h limit needs its own signs.","source":"https://www.government.nl/site/binaries/site-content/collections/documents/2024/02/09/road-traffic-signs-and-regulations-in-the-netherlands/Road+Traffic+Signs+and+Regulations+in+the+Netherlands.pdf#page=26"},{"t":"Speed limits","q":"You drive on the motorway with a bicycle rack on the back of your car. What is your maximum speed?","o":["90 km/h, as with a trailer","The same as without the rack","80 km/h at all times","100 km/h at all times"],"c":1,"e":"A bicycle rack does not change your speed limits. The 90 km/h limit is for towing a trailer.","source":"https://www.rijksoverheid.nl/vraag-en-antwoord/verkeersveiligheid/wat-is-de-maximumsnelheid-voor-auto-s-op-de-snelweg"},{"t":"Speed limits","q":"A white rectangular sign shows the word ZONE and a red-bordered circle with 30. What does it mean?","o":["Advisory speed of 30 km/h","Max 30 km/h until the next junction","Minimum speed of 30 km/h","Max 30 km/h until the end-of-zone sign"],"c":3,"e":"A zone sign sets the limit for the whole area, not just one road section, until you pass the end-of-zone sign.","source":"https://www.anwb.nl/verkeer/nederland/verkeersinformatie/verkeersborden-nederland"},{"t":"Distances","q":"You drive in thick fog and can see 40 m of clear road ahead. What decides your maximum safe speed?","o":["Stopping within the 40 m you can see","The speed limit on the signs","The speed of the car in front","Whether your fog lights are switched on"],"c":0,"e":"You must always be able to stop within the distance you can see to be clear. The posted limit is only a maximum.","source":"https://www.government.nl/site/binaries/site-content/collections/documents/2024/02/09/road-traffic-signs-and-regulations-in-the-netherlands/Road+Traffic+Signs+and+Regulations+in+the+Netherlands.pdf#page=26"},{"t":"Distances","q":"At 120 km/h, about how far do you travel in one second?","o":["About 12 m","About 20 m","About 33 m","About 60 m"],"c":2,"e":"120 km/h divided by 3.6 is about 33 metres per second. Dividing by 10 is a common mistake.","source":"https://www.anwb.nl/verkeer/veiligheid/verkeersregels/afstand-houden"},{"t":"Distances","q":"You double your speed. What happens to your reaction distance (the distance covered before you start braking)?","o":["It stays the same","It quadruples","It doubles","It halves"],"c":2,"e":"In your reaction time you keep driving at the same speed, so reaction distance grows in step with speed. Braking distance is the one that quadruples.","source":"https://www.anwb.nl/verzekeringen/autoverzekering/veilig-rijden/rijtips-snelheid"},{"t":"Stopping & parking","q":"A bus stop has no yellow block marking. Within what distance of the bus stop sign may you not stop?","o":["12 m","5 m","15 m","20 m"],"c":0,"e":"Without the block marking, stopping is banned within 12 m of the bus stop sign. The 5 m rule is for crossings and junctions.","source":"https://wetten.overheid.nl/jci1.3:c:BWBR0004825&artikel=23"},{"t":"Stopping & parking","q":"At a bus stop with yellow block marking, may you stop briefly to let a passenger get out at once?","o":["No, not even for a moment, as a bus may arrive","Only outside the hours that buses are running","Only if your hazard lights are switched on","Yes, letting a passenger in or out is allowed"],"c":3,"e":"The stopping ban at a bus stop does not apply to letting passengers get in or out at once.","source":"https://wetten.overheid.nl/jci1.3:c:BWBR0004825&artikel=23"},{"t":"Stopping & parking","q":"May you stop on a cycle lane (fietsstrook) to let a passenger out?","o":["Yes, for passengers only","No, that is not allowed","Yes, if no cyclist is close","Yes, for up to three minutes"],"c":1,"e":"You may not stop on a cycle lane. The exception for letting passengers out applies only at bus stops.","source":"https://wetten.overheid.nl/jci1.3:c:BWBR0004825&artikel=23"},{"t":"Stopping & parking","q":"Is it allowed to stop voluntarily in a road tunnel, for example to let a passenger out?","o":["Yes, close to the right-hand wall","No, that is never allowed","Yes, with your hazard lights on","Yes, for a maximum of one minute"],"c":1,"e":"Stopping in a tunnel is banned. Hazard lights do not make it legal.","source":"https://wetten.overheid.nl/jci1.3:c:BWBR0004825&artikel=23"},{"t":"Stopping & parking","q":"May you park in front of the entrance or exit of a driveway (inrit or uitrit)?","o":["Yes, if you stay close to your car","Yes, but only at night","Yes, if the driveway is not in use","No, that is not allowed"],"c":3,"e":"Parking in front of an entrance or exit is banned, whatever the time of day.","source":"https://wetten.overheid.nl/jci1.3:c:BWBR0004825&artikel=24"},{"t":"Stopping & parking","q":"Outside a built-up area, may you park on the carriageway of a priority road?","o":["No, that is not allowed","Yes, if there is no parking ban sign","Yes, with your parking lights on","Yes, but only during the day"],"c":0,"e":"Outside built-up areas parking on the carriageway of a priority road is banned, even without a sign.","source":"https://wetten.overheid.nl/jci1.3:c:BWBR0004825&artikel=24"},{"t":"Stopping & parking","q":"Inside a built-up area, may you park on the carriageway of a priority road?","o":["No, never on a priority road","Only during the night","Yes, unless signs or markings forbid it","Only with hazard lights on"],"c":2,"e":"The ban on parking on a priority road applies only outside built-up areas. Inside them you may park unless signs or markings say otherwise.","source":"https://www.anwb.nl/verkeer/veiligheid/verkeersregels/voorrang-buiten-de-bebouwde-kom"},{"t":"Stopping & parking","q":"In a blue zone you arrive at 10:10. Which arrival time may you set on your parking disc?","o":["10:00","11:00","10:30","10:15"],"c":2,"e":"You may round your arrival time up to the next half hour or full hour, which here is 10:30. Setting an earlier time is not allowed.","source":"https://www.government.nl/site/binaries/site-content/collections/documents/2024/02/09/road-traffic-signs-and-regulations-in-the-netherlands/Road+Traffic+Signs+and+Regulations+in+the+Netherlands.pdf#page=30"},{"t":"Stopping & parking","q":"You leave your car next to a car parked at the kerb while you buy a coffee for two minutes. Is that allowed?","o":["No, that is double parking","Yes, if it takes under three minutes","Yes, with your hazard lights on","Yes, if the street is wide enough"],"c":0,"e":"Leaving your car for any reason other than passengers or loading is parking, and double parking is banned. There is no time allowance.","source":"https://www.government.nl/site/binaries/site-content/collections/documents/2024/02/09/road-traffic-signs-and-regulations-in-the-netherlands/Road+Traffic+Signs+and+Regulations+in+the+Netherlands.pdf#page=29"},{"t":"Stopping & parking","q":"Your grandmother's disabled parking card is in your car, but she is at home. May you park in a general disabled parking space?","o":["Yes, a displayed card is enough","Yes, but only for a maximum of two hours","Yes, because you are a family member","No; she must be travelling with you"],"c":3,"e":"Using a disabled parking space with a card is only allowed when the parking is directly linked to transporting the card holder.","source":"https://www.government.nl/site/binaries/site-content/collections/documents/2024/02/09/road-traffic-signs-and-regulations-in-the-netherlands/Road+Traffic+Signs+and+Regulations+in+the+Netherlands.pdf#page=51"},{"t":"Motorway","q":"You have missed your exit on the motorway. What may you do?","o":["Reverse carefully on the hard shoulder","Drive on to the next exit","Make a U-turn through a gap in the barrier","Stop on the hard shoulder and wait for a gap"],"c":1,"e":"Reversing, U-turns and stopping on the carriageway are banned on motorways. The only option is the next exit.","source":"https://www.government.nl/site/binaries/site-content/collections/documents/2024/02/09/road-traffic-signs-and-regulations-in-the-netherlands/Road+Traffic+Signs+and+Regulations+in+the+Netherlands.pdf#page=34"},{"t":"Lane use","q":"On a motorway with three lanes in your direction you tow a caravan (combination longer than 7 m). Which lanes may you use?","o":["All three lanes","Only the two right-hand lanes","Only the right-hand lane","Only the left-hand lane, to overtake"],"c":1,"e":"On motorways with three or more lanes, combinations longer than 7 m may only use the two right-hand lanes.","source":"https://www.government.nl/site/binaries/site-content/collections/documents/2024/02/09/road-traffic-signs-and-regulations-in-the-netherlands/Road+Traffic+Signs+and+Regulations+in+the+Netherlands.pdf#page=35"},{"t":"Safety","q":"Your car breaks down on the motorway and you stop on the hard shoulder next to a guardrail. What should you and your passengers do?","o":["Stay in the car with seatbelts fastened","Stand behind the car so traffic sees you","Exit on the left and set up a triangle","Exit on the right and wait behind the guardrail"],"c":3,"e":"Get out on the right side and move as far as possible behind the guardrail or into the verge. Staying in the car or standing on the hard shoulder is dangerous.","source":"https://www.rijkswaterstaat.nl/wegen/ongeval-en-pech/pech-op-de-spitsstrook"},{"t":"Safety","q":"Your car breaks down in a tunnel and you cannot drive out. Where should your passengers wait?","o":["50 m past the car, by the tunnel wall","Inside the car with seatbelts on","Behind the car, next to a warning triangle","On the road, waving traffic around the car"],"c":0,"e":"Rijkswaterstaat advises passengers to stand 50 m beyond the vehicle, close to the tunnel wall, while you walk to the help point.","source":"https://www.rijkswaterstaat.nl/wegen/ongeval-en-pech/pech-file-ongeval-of-brand-in-een-tunnel"},{"t":"Lights & visibility","q":"Your car has daytime running lights. You enter a tunnel during the day. What do you do?","o":["Nothing; daytime running lights are enough","Switch on the front fog lights","Switch on dipped headlights","Switch on the hazard lights"],"c":2,"e":"Daytime running lights are not enough in a tunnel. Use dipped headlights.","source":"https://www.anwb.nl/vakantie/nederland/informatie/verkeersregels"},{"t":"Lights & visibility","q":"When may you flash your headlights at another road user?","o":["To let another driver go first","To thank a driver who let you in","Only to warn of danger","To ask a slower car to move over"],"c":2,"e":"You may only sound your horn or flash your headlights to warn of danger. Flashing to let someone go first is common in other countries but not allowed here.","source":"https://www.government.nl/site/binaries/site-content/collections/documents/2024/02/09/road-traffic-signs-and-regulations-in-the-netherlands/Road+Traffic+Signs+and+Regulations+in+the+Netherlands.pdf#page=30"},{"t":"Alcohol limit","q":"You got your first driving licence 6 years ago. What blood alcohol limit applies to you?","o":["0.5 per mille","0.2 per mille","0.8 per mille","0.0 per mille"],"c":0,"e":"After 5 years you are an experienced driver and the 0.5 limit applies. The 0.2 limit is for novice drivers in their first 5 years.","source":"https://www.rijksoverheid.nl/vraag-en-antwoord/verkeersveiligheid/mag-ik-met-alcohol-op-deelnemen-aan-het-verkeer"},{"t":"Alcohol limit","q":"The police give you a saliva test (speekseltest) and it is positive for drugs. What happens next?","o":["You pay a fine on the spot and drive on","Your licence is cancelled straight away","You are tested again a week later","You must give blood for a drug test"],"c":3,"e":"A positive saliva test is followed by a blood test, which decides whether you were over the limit.","source":"https://www.rijksoverheid.nl/themas/familie-zorg-en-gezondheid/drugs/vraag-en-antwoord/verkeersveiligheid/drugs-in-het-verkeer"},{"t":"Mobile phones","q":"Which of these is allowed while you are driving?","o":["Holding the phone on speaker near your mouth","Using navigation on a phone in a holder","Clamping the phone between ear and shoulder","Typing a short message at low speed"],"c":1,"e":"A phone in a holder may be used, for example for navigation. Holding it in any way, including between ear and shoulder, is not allowed while driving.","source":"https://www.rijksoverheid.nl/themas/verkeer-en-vervoer/auto/vraag-en-antwoord/voertuigen-op-de-weg/mag-ik-appen-bellen-en-naar-muziek-luisteren-als-ik-op-de-weg-rijd"},{"t":"Seatbelts","q":"May you put a rear-facing baby seat on the front passenger seat?","o":["Yes, always","Only if the front airbag is switched off","No, never","Only for short trips"],"c":1,"e":"A rear-facing child seat may only go on a front seat when the airbag there is switched off.","source":"https://www.anwb.nl/auto/autostoeltjes/regels-autostoeltje"},{"t":"Seatbelts","q":"Two child seats are fitted and in use on the back seat, with no room for a third. Your third child is 4 years old (1.10 m). What is allowed?","o":["Front seat with the normal seat belt","On an adult's lap in the back","Not at all in this car","Back seat with the normal seat belt"],"c":3,"e":"A child of 3 or older may use the normal seat belt in the back if two child seats there leave no room for a third. Sitting in front without a child seat is not allowed.","source":"https://www.anwb.nl/auto/autostoeltjes/regels-autostoeltje"},{"t":"Vehicle condition","q":"What is the legal minimum tread depth for car tyres in the Netherlands?","o":["1.6 mm","3 mm","4 mm","1 mm"],"c":0,"e":"The legal minimum is 1.6 mm for summer and winter tyres. Some other countries require more for winter tyres.","source":"https://www.anwb.nl/auto/banden/profieldiepte"},{"t":"Safety","q":"You are a novice driver (beginnersrijbewijs) and commit a serious offence, such as tailgating, for the second time. What happens?","o":["You only receive a warning letter","Nothing; only a third offence counts","The CBR investigates your driving ability","You pay a double fine and nothing else"],"c":2,"e":"After the second serious offence the Public Prosecution Service reports you to the CBR, which investigates your driving ability.","source":"https://www.rijksoverheid.nl/onderwerpen/rijbewijs/puntenrijbewijs-beginnersrijbewijs"},{"t":"Safety","q":"Who may act as the coach (begeleider) of a 17-year-old with a car licence?","o":["Anyone 21 or older with a car licence","Only a parent, with any car licence","Someone 27 or older, licensed 5+ years","Only a qualified driving instructor"],"c":2,"e":"A coach must be at least 27 and have held a car licence for at least 5 years. Being a parent is not required.","source":"https://www.rijksoverheid.nl/vraag-en-antwoord/rijbewijs/hoe-word-ik-begeleider-van-een-17-jarige-bestuurder"},{"t":"Railway crossings","q":"Traffic ahead of you is queuing just beyond a level crossing. May you stop on the crossing?","o":["No; wait before it until there is room","Yes, if the barriers are up","Yes, if no lights are flashing","Yes, with hazard lights on"],"c":0,"e":"Stopping on a level crossing is banned. Wait before the crossing until there is space to clear it completely.","source":"https://wetten.overheid.nl/jci1.3:c:BWBR0004825&artikel=23"},{"t":"Distances","num":true,"q":"At 108 km/h with a reaction time of 1 second, how many metres do you travel before you start braking? (type a number)","a":["30"],"e":"108 divided by 3.6 is 30 m per second, so 30 m of reaction distance. That is before the brakes do anything.","source":"https://www.anwb.nl/verzekeringen/autoverzekering/veilig-rijden/rijtips-snelheid"},{"t":"Distances","num":true,"q":"You increase your speed from 30 km/h to 90 km/h. How many times longer does your braking distance become? (type a number)","a":["9","nine"],"e":"Braking distance grows with the square of speed: 3 times faster means 3 x 3 = 9 times longer. It is not 3.","source":"https://www.anwb.nl/verzekeringen/autoverzekering/veilig-rijden/rijtips-snelheid"},{"t":"Distances","num":true,"q":"Using the 2-second rule at 90 km/h, how many metres should you keep behind the car in front? (type a number)","a":["50"],"e":"90 km/h is 25 m per second, so 2 seconds is 50 m.","source":"https://www.anwb.nl/verkeer/veiligheid/verkeersregels/afstand-houden"},{"t":"Speed limits","num":true,"q":"What is the maximum speed in km/h for a passenger car towing a trailer (maximum mass up to 3500 kg) on the motorway? (type a number)","a":["90"],"e":"With a trailer up to 3500 kg the limit is 90 km/h, even where cars may drive 100 or 130.","source":"https://www.rijksoverheid.nl/vraag-en-antwoord/verkeersveiligheid/wat-is-de-maximumsnelheid-voor-auto-s-op-de-snelweg"},{"t":"Distances","num":true,"q":"You tow another car. What is the maximum distance in metres between the back of your car and the front of the towed car? (type a number)","a":["5"],"e":"The gap between a towing and a towed vehicle may not be more than 5 m.","source":"https://www.government.nl/site/binaries/site-content/collections/documents/2024/02/09/road-traffic-signs-and-regulations-in-the-netherlands/Road+Traffic+Signs+and+Regulations+in+the+Netherlands.pdf#page=36"},{"t":"Distances","num":true,"q":"Your stationary car is a hazard to traffic and your hazard lights do not work. About how many metres behind the car do you place the warning triangle? (type a number)","a":["30"],"e":"Place the warning triangle about 30 m from the vehicle, facing approaching traffic. With working hazard lights a triangle is not required.","source":"https://www.government.nl/site/binaries/site-content/collections/documents/2024/02/09/road-traffic-signs-and-regulations-in-the-netherlands/Road+Traffic+Signs+and+Regulations+in+the+Netherlands.pdf#page=37"}],"civic":[{"sec":"knm","t":"Work life","q":"Samira krijgt een tijdelijk contract van 6 maanden. Haar werkgever wil een proeftijd van 1 maand. Mag dat?","o":["Ja, 1 maand proeftijd mag altijd.","Nee, bij dit contract mag geen proeftijd.","Ja, maar alleen als zij ouder is dan 21.","Nee, de proeftijd moet dan 2 maanden zijn."],"c":1,"en":"Samira gets a temporary contract of 6 months. Her employer wants a probation period of 1 month. Is that allowed?","e":"With a temporary contract of 6 months or shorter, the employer may not agree a probation period at all. The trap is thinking 1 month is always fine; that applies to contracts longer than 6 months but under 2 years.","source":"https://www.rijksoverheid.nl/onderwerpen/arbeidsovereenkomst-en-cao/vraag-en-antwoord/hoelang-duurt-een-proeftijd"},{"sec":"knm","t":"Work life","q":"Hoeveel vakantiegeld krijgt een werknemer minimaal?","o":["4% van het brutosalaris per jaar","1 extra maandsalaris per jaar","8% van het brutosalaris per jaar","100 euro per week vakantie"],"c":2,"en":"What is the minimum holiday allowance an employee receives?","e":"Holiday allowance (vakantiegeld) is at least 8% of your gross annual salary, and most people get it in May or June. It is not a fixed extra month's salary.","source":"https://www.rijksoverheid.nl/onderwerpen/vakantiedagen-en-vakantiegeld/vraag-en-antwoord/hoe-hoog-is-mijn-vakantiegeld"},{"sec":"knm","t":"Work life","q":"Karim is al 3 maanden ziek. Hoeveel loon moet zijn werkgever in het eerste ziektejaar minimaal betalen?","o":["Niets, want Karim werkt nu niet.","Minstens 50% van zijn loon.","Alleen de helft van het minimumloon.","Minstens 70% van zijn loon."],"c":3,"en":"Karim has been ill for 3 months. How much wage must his employer pay at minimum in the first year of illness?","e":"In the first year of illness the employer pays at least 70% of the wage, and not less than the minimum wage. Being sick does not mean you lose all your pay.","source":"https://www.rijksoverheid.nl/vraag-en-antwoord/ziekteverzuim-van-het-werk/hoeveel-loon-krijg-ik-doorbetaald-als-ik-ziek-ben"},{"sec":"knm","t":"Work life","q":"Lisa is 4 maanden ziek. Haar baas zegt: 'Ik ontsla je, want je bent ziek.' Wat is waar?","o":["Dat mag meestal niet in de eerste 2 jaar.","Dat mag, na 3 maanden ziekte mag ontslag.","Dat mag, als hij het in een brief schrijft."],"c":0,"en":"Lisa has been ill for 4 months. Her boss says: 'I am firing you because you are ill.' What is true?","e":"During the first 2 years of illness an employee may in principle not be dismissed, with only a few exceptions. Putting it in a letter does not make it allowed.","source":"https://www.rijksoverheid.nl/onderwerpen/ontslag/vraag-en-antwoord/mag-ik-worden-ontslagen-als-ik-ziek-of-arbeidsongeschikt-ben"},{"sec":"knm","t":"Work life","q":"Tom verliest zijn baan. Hij wil een WW-uitkering van het UWV. Wanneer moet hij die uiterlijk aanvragen?","o":["Binnen 1 week na zijn eerste werkloze dag","Binnen 3 maanden na zijn laatste werkdag","Pas als hij 1 maand geen werk heeft","Binnen 1 jaar, via de gemeente"],"c":0,"en":"Tom loses his job. He wants unemployment benefit (WW) from UWV. What is the latest moment to apply?","e":"You can apply for WW from 1 week before and at the latest 1 week after your first day of unemployment. Waiting longer can mean a lower benefit or none for a period.","source":"https://www.uwv.nl/nl/ww/ww-aanvragen"},{"sec":"knm","t":"Work life","q":"Op uw werk is een machine niet veilig. Wat doet u eerst?","o":["U belt meteen de politie.","U stuurt een brief naar de gemeente.","U stopt en gaat naar huis.","U bespreekt het met uw werkgever."],"c":3,"en":"At your work a machine is not safe. What do you do first?","e":"Always discuss a complaint about working conditions with your employer first. Only if that does not help do you go to an arbo expert and then the Nederlandse Arbeidsinspectie.","source":"https://www.rijksoverheid.nl/onderwerpen/arbeidsomstandigheden/vraag-en-antwoord/klacht-over-arbeidsomstandigheden"},{"sec":"knm","t":"Work life","q":"Ahmed begint een eigen bedrijf. Hij stuurt zijn eerste factuur. Wat moet hij binnen een week doen?","o":["Een brief sturen naar de SVB","Zich melden bij het UWV","Zich inschrijven bij de KVK","Een vergunning halen bij de politie"],"c":2,"en":"Ahmed starts his own business. He sends his first invoice. What must he do within a week?","e":"A new business must register with the Kamer van Koophandel (KVK) within one week of the start date, for example after the first invoice. UWV and SVB deal with benefits, not business registration.","source":"https://www.kvk.nl/starten/op-welke-datum-moet-ik-mijn-bedrijf-inschrijven-bij-kvk/"},{"sec":"knm","t":"Work life","q":"Op welke leeftijd krijgen mensen in 2026 AOW, het pensioen van de overheid?","o":["Op 65 jaar","Op 70 jaar","Op 67 jaar","Op 62 jaar"],"c":2,"en":"At what age do people receive AOW, the state pension, in 2026?","e":"The AOW age is 67 in 2026 and 2027; from 2028 it becomes 67 and 3 months. 65 was the old AOW age.","source":"https://www.rijksoverheid.nl/themas/belastingen-uitkeringen-en-toeslagen/algemene-ouderdomswet-aow/aow-leeftijd"},{"sec":"knm","t":"Healthcare","q":"Maria komt in Nederland werken. Binnen hoeveel tijd moet zij een Nederlandse zorgverzekering afsluiten?","o":["Binnen 4 weken","Binnen 4 maanden","Binnen 1 jaar","Het hoeft niet, het is vrijwillig"],"c":1,"en":"Maria comes to work in the Netherlands. Within how much time must she take out Dutch health insurance?","e":"Basic health insurance is compulsory, and you must arrange it within 4 months. Don't confuse 4 months with 4 weeks.","source":"https://www.rijksoverheid.nl/onderwerpen/immigratie-naar-nederland/vraag-en-antwoord/moet-ik-een-zorgverzekering-afsluiten-als-ik-in-nederland-ga-werken"},{"sec":"knm","t":"Healthcare","q":"Uw zoon van 10 moet naar het ziekenhuis. Betaalt u eigen risico voor hem?","o":["Nee, voor kinderen tot 18 jaar niet.","Ja, hetzelfde bedrag als voor volwassenen.","Ja, maar alleen de helft van het bedrag."],"c":0,"en":"Your 10-year-old son has to go to hospital. Do you pay the deductible (eigen risico) for him?","e":"Children under 18 do not pay eigen risico. They are insured through their parents' policy at no extra cost.","source":"https://www.rijksoverheid.nl/documenten/vraag-en-antwoord/zorgverzekering/eigen-risico-zorgverzekering"},{"sec":"knm","t":"Healthcare","q":"Jan is 35 jaar. Hij gaat naar de tandarts voor een gewone controle. Betaalt de basisverzekering dat?","o":["Ja, de basisverzekering betaalt alles.","Nee, niet uit de basisverzekering.","Ja, maar alleen één keer per jaar.","Nee, alleen de huisarts doet controles."],"c":1,"en":"Jan is 35. He goes to the dentist for a normal check-up. Does basic insurance pay for that?","e":"For adults, basic insurance only covers things like dental surgery and dentures, not routine check-ups. Adults pay these themselves or take an extra (aanvullende) insurance; children under 18 are covered.","source":"https://www.rijksoverheid.nl/vraag-en-antwoord/zorgverzekering/krijg-ik-tandartskosten-vergoed"},{"sec":"knm","t":"Healthcare","q":"U wilt naar een specialist in het ziekenhuis. Wat heeft u meestal nodig?","o":["Een formulier van de apotheek","Een brief van de gemeente","Een verwijsbrief van de huisarts","Een afspraak bij de huisartsenpost"],"c":2,"en":"You want to see a specialist in hospital. What do you usually need?","e":"For specialist care, such as in a hospital, you need a referral letter (verwijsbrief) from your GP. The huisarts is the first stop, not the huisartsenpost or the gemeente.","source":"https://www.rijksoverheid.nl/onderwerpen/eerstelijnszorg/vraag-en-antwoord/wanneer-heb-ik-een-verwijsbrief-van-mijn-huisarts-nodig-en-wanneer-mag-hij-deze-weigeren"},{"sec":"knm","t":"Healthcare","q":"U heeft een baby van 2 maanden. U heeft vragen over voeding en groei. Waar kunt u gratis terecht?","o":["Bij de huisartsenpost","Bij het UWV","Bij de apotheek","Bij het consultatiebureau"],"c":3,"en":"You have a 2-month-old baby. You have questions about feeding and growth. Where can you go for free?","e":"The consultatiebureau gives free youth health care for children aged 0 to 4, including advice and vaccinations. The huisartsenpost is only for urgent care outside office hours.","source":"https://www.rijksoverheid.nl/onderwerpen/zwangerschap-en-geboorte/vraag-en-antwoord/bij-wie-kan-ik-terecht-met-vragen-over-de-gezondheid-en-opvoeding-van-mijn-kind"},{"sec":"knm","t":"Healthcare","q":"U ruikt op straat een sterke gaslucht. Wat doet u?","o":["U belt 112.","U belt 0900-8844.","U belt de gemeente.","U belt uw huisarts."],"c":0,"en":"You smell a strong smell of gas in the street. What do you do?","e":"112 is for life-threatening situations, and a strong gas smell in the street is one of the examples. 0900-8844 is the police number for situations that are not urgent.","source":"https://www.rijksoverheid.nl/vraag-en-antwoord/alarmnummer-112/wanneer-112-bellen"},{"sec":"knm","t":"Healthcare","q":"U wilt zich inschrijven bij een huisarts. De huisarts zegt nee, want u woont te ver weg. Mag dat?","o":["Nee, een huisarts moet iedereen nemen.","Ja, dat mag in sommige situaties.","Nee, alleen de gemeente mag nee zeggen."],"c":1,"en":"You want to register with a GP. The GP says no because you live too far away. Is that allowed?","e":"You can usually choose your own GP, but a GP may refuse new patients in some cases, for example if you live too far away or the practice is full. Your health insurer can help you find one.","source":"https://www.rijksoverheid.nl/onderwerpen/eerstelijnszorg/vraag-en-antwoord/ben-ik-vrij-om-zelf-een-huisarts-te-kiezen-en-hoe-verander-ik-van-huisarts"},{"sec":"knm","t":"Housing","q":"U wilt verhuizen en de huur van uw woning opzeggen. Hoe doet u dat het best?","o":["Met een berichtje aan de buren","Met een aangetekende brief","Met een telefoontje naar de gemeente","Door te stoppen met betalen"],"c":1,"en":"You want to move and end the rental contract of your home. What is the best way to do that?","e":"You end the rental with a registered letter (aangetekende brief) to the landlord and keep the receipt. Simply stopping payment does not end the contract.","source":"https://www.rijksoverheid.nl/onderwerpen/woning-huren/vraag-en-antwoord/huur-opzeggen-woning"},{"sec":"knm","t":"Housing","q":"Malik tekent in 2026 een nieuw huurcontract. De verhuurder vraagt een borg van 4 maanden huur. Mag dat?","o":["Nee, maximaal 2 maanden kale huur.","Ja, de verhuurder mag dat zelf kiezen.","Ja, als Malik een student is.","Nee, een borg is altijd verboden."],"c":0,"en":"Malik signs a new rental contract in 2026. The landlord asks for a deposit of 4 months' rent. Is that allowed?","e":"For contracts from 1 July 2023 the deposit may be at most 2 months' basic rent (kale huur). A deposit itself is allowed, just not more than that.","source":"https://www.rijksoverheid.nl/vraag-en-antwoord/woning-huren/woning-huren-waarborgsom"},{"sec":"knm","t":"Housing","q":"De kraan in uw huurhuis lekt. Er moet een nieuw leertje (rubbertje) in. Wie moet dat regelen?","o":["De verhuurder","De huurder zelf","De buren","De gemeente"],"c":1,"en":"The tap in your rented home is leaking. It needs a new washer. Who has to arrange that?","e":"Small, daily maintenance such as a new tap washer is the tenant's job. Big repairs and outside painting are for the landlord.","source":"https://www.rijksoverheid.nl/onderwerpen/woning-huren/vraag-en-antwoord/welke-kosten-zijn-voor-de-huurder-en-welke-voor-de-verhuurder"},{"sec":"knm","t":"Housing","q":"U huurt een appartement. Er hangt geen rookmelder. Wie moet zorgen dat er een rookmelder is?","o":["De brandweer","De verhuurder","De gemeente","Niemand, het is niet verplicht"],"c":1,"en":"You rent an apartment. There is no smoke alarm. Who must make sure there is a smoke alarm?","e":"A smoke alarm is required on every floor with a living room, bedroom or kitchen, and in a rented home the landlord must provide it. It is not optional.","source":"https://www.rijksoverheid.nl/onderwerpen/gezond-en-veilig-wonen/vraag-en-antwoord/hoeveel-rookmelders-moet-ik-in-mijn-huis-hebben"},{"sec":"knm","t":"Housing","q":"Uw verhuurder repareert een kapot raam niet. Wat is de eerste stap?","o":["Meteen met een advocaat naar de rechter gaan","Stoppen met het betalen van de huur","Een brief of e-mail sturen naar de verhuurder","De politie bellen op 0900-8844"],"c":2,"en":"Your landlord does not repair a broken window. What is the first step?","e":"First report the problem in writing to the landlord and give a deadline (for example 6 weeks). Only after that do you go to the Huurcommissie, the gemeente or a judge; stopping rent payment is not the way.","source":"https://www.rijksoverheid.nl/onderwerpen/woning-huren/vraag-en-antwoord/hoe-zorg-ik-ervoor-dat-de-verhuurder-slecht-onderhoud-aanpakt"},{"sec":"knm","t":"Housing","q":"Hoe vaak mag een verhuurder de huur verhogen?","o":["1 keer per 12 maanden","Elke maand","2 keer per jaar","Nooit"],"c":0,"en":"How often may a landlord raise the rent?","e":"A landlord may raise the rent once every 12 months, often on 1 July. Rent increases are allowed, but not more often than that.","source":"https://www.rijksoverheid.nl/vraag-en-antwoord/woning-huren/welke-regels-gelden-er-voor-een-huurverhoging"},{"sec":"knm","t":"Education","q":"Youssef is 16 jaar. Hij heeft nog geen diploma havo, vwo of mbo 2. Moet hij nog naar school?","o":["Nee, vanaf 16 jaar is school niet verplicht.","Ja, hij moet naar school tot hij 21 jaar is.","Ja, tot 18 jaar of tot hij zo'n diploma heeft."],"c":2,"en":"Youssef is 16. He does not yet have a havo, vwo or mbo level 2 diploma. Does he still have to go to school?","e":"Young people aged 16 to 18 without a startkwalificatie (havo, vwo or mbo 2) have a kwalificatieplicht and must keep learning. The trap is thinking school ends at 16.","source":"https://www.rijksoverheid.nl/themas/onderwijs/leerplicht/leerplicht-en-kwalificatieplicht"},{"sec":"knm","t":"Education","q":"Door zijn werk kan Ali in geen enkele schoolvakantie weg. Hij wil met zijn dochter van 8 buiten de schoolvakantie op vakantie. Aan wie vraagt hij toestemming?","o":["Aan de leraar van zijn dochter","Aan de directeur van de school","Aan de gemeente","Aan zijn eigen werkgever"],"c":1,"en":"Because of his work, Ali cannot go away in any school holiday. He wants to take his 8-year-old daughter on holiday outside the school holidays. Who does he ask for permission?","e":"Only in special cases, such as work, the school director (directeur) may give up to 10 days off once per school year; ask at least 8 weeks in advance. The teacher cannot decide this.","source":"https://www.rijksoverheid.nl/documenten/vraag-en-antwoord/leerplicht/leerplicht-schoolvakanties"},{"sec":"knm","t":"Education","q":"De school vraagt een vrijwillige ouderbijdrage voor het schoolreisje. U betaalt niet. Mag uw kind mee?","o":["Nee, alleen kinderen van betalende ouders.","Ja, maar het kind betaalt de reis zelf.","Ja, uw kind mag gewoon mee.","Nee, uw kind krijgt een andere activiteit."],"c":2,"en":"The school asks a voluntary parental contribution for the school trip. You do not pay. May your child go?","e":"The ouderbijdrage is voluntary, and the school may not exclude a child or give a replacement activity when parents do not pay.","source":"https://www.rijksoverheid.nl/documenten/vraag-en-antwoord/financiering-onderwijs/is-de-vrijwillige-ouderbijdrage-op-de-basisschool-en-middelbare-school-verplicht"},{"sec":"knm","t":"Education","q":"Welke middelbare school duurt 6 jaar en bereidt voor op de universiteit?","o":["het vmbo","de havo","het vwo","het mbo"],"c":2,"en":"Which type of secondary school takes 6 years and prepares for university?","e":"Vwo takes 6 years and prepares for university. Havo (5 years) prepares mainly for hbo, vmbo (4 years) for mbo, and mbo is not a secondary school.","source":"https://www.rijksoverheid.nl/onderwerpen/voortgezet-onderwijs/vraag-en-antwoord/hoe-zit-het-vwo-in-elkaar"},{"sec":"knm","t":"Education","q":"Uw dochter gaat studeren aan de hogeschool. Waar vraagt zij studiefinanciering aan?","o":["Bij de gemeente","Bij de SVB","Bij het UWV","Bij DUO"],"c":3,"en":"Your daughter is going to study at a university of applied sciences. Where does she apply for student finance?","e":"DUO (Dienst Uitvoering Onderwijs) handles student finance. SVB pays child benefit and AOW, UWV handles unemployment benefits.","source":"https://duo.nl/particulier/studiefinanciering/"},{"sec":"knm","t":"Government","q":"Wie kiezen de 75 leden van de Eerste Kamer?","o":["Alle Nederlanders van 18 jaar en ouder","De leden van de Tweede Kamer","De koning en de minister-president","De leden van de Provinciale Staten"],"c":3,"en":"Who elects the 75 members of the Eerste Kamer (Senate)?","e":"The members of the twelve Provinciale Staten elect the Eerste Kamer. Citizens vote directly for the Tweede Kamer, not for the Eerste Kamer.","source":"https://www.eerstekamer.nl/faq/hoe_wordt_de_eerste_kamer_gekozen"},{"sec":"knm","t":"Government","q":"Hoe krijgt een gemeente een nieuwe burgemeester?","o":["De Kroon benoemt de burgemeester.","De inwoners kiezen de burgemeester.","De wethouders kiezen de burgemeester.","De Tweede Kamer kiest de burgemeester."],"c":0,"en":"How does a municipality get a new mayor?","e":"The mayor is appointed by the Crown (the King and the Minister of the Interior) for 6 years, based on a recommendation by the gemeenteraad. Residents do not vote for the mayor directly.","source":"https://www.rijksoverheid.nl/themas/overheid-en-democratie/gemeenten/burgemeesters"},{"sec":"knm","t":"Elections","q":"Wie mag stemmen bij de Tweede Kamerverkiezingen?","o":["Iedereen die 5 jaar in Nederland woont","Alleen mensen met een baan","Iedereen van 16 jaar en ouder","Nederlanders van 18 jaar en ouder"],"c":3,"en":"Who may vote in the Tweede Kamer elections?","e":"To vote for the Tweede Kamer you need Dutch nationality and must be 18 or older. Living here 5 years only gives non-EU residents the right to vote for the gemeenteraad.","source":"https://www.kiesraad.nl/verkiezingen/tweede-kamer/stemmen/kiesgerechtigdheid"},{"sec":"knm","t":"Government","q":"Wat staat er in artikel 1 van de Grondwet?","o":["In gelijke gevallen behandelen we iedereen gelijk.","Iedereen in Nederland moet Nederlands spreken.","De koning maakt alle wetten van het land.","Iedereen moet stemmen bij de verkiezingen."],"c":0,"en":"What does article 1 of the Constitution say?","e":"Article 1 says everyone in the Netherlands is treated equally in equal cases, and discrimination on any ground is not allowed. The other options are not in the Constitution.","source":"https://www.denederlandsegrondwet.nl/artikel/2008/1-gelijke-behandeling-en-discriminatieverbod"},{"sec":"knm","t":"Government","q":"Wie is tegenover het parlement verantwoordelijk voor wat de koning als staatshoofd doet?","o":["De koning zelf","De ministers","De burgemeesters","De rechters"],"c":1,"en":"Who is accountable to parliament for what the King does as head of state?","e":"The Constitution says the King is inviolable and the ministers are responsible (ministeriële verantwoordelijkheid). That is why a minister also signs laws and royal decrees.","source":"https://www.koninklijkhuis.nl/onderwerpen/rol-van-het-staatshoofd/vraag-en-antwoord/wat-houdt-ministeriele-verantwoordelijkheid-in"},{"sec":"knm","t":"Elections","q":"Welke verkiezingen zijn er elke 5 jaar?","o":["Voor de gemeenteraad","Voor de Provinciale Staten","Voor het Europees Parlement","Voor de Tweede Kamer"],"c":2,"en":"Which elections take place every 5 years?","e":"European Parliament elections are every 5 years. All other elections (Tweede Kamer, gemeenteraad, Provinciale Staten, waterschap) are every 4 years.","source":"https://www.rijksoverheid.nl/onderwerpen/verkiezingen/vraag-en-antwoord/welke-verkiezingen-zijn-er"},{"sec":"knm","t":"Elections","q":"Hoe vaak kiezen de inwoners een nieuwe gemeenteraad?","o":["Elke 4 jaar","Elke 2 jaar","Elk jaar","Elke 6 jaar"],"c":0,"en":"How often do residents elect a new municipal council?","e":"Gemeenteraad elections are held every 4 years. 6 years is the term of a burgemeester, which is a common mix-up.","source":"https://www.rijksoverheid.nl/onderwerpen/verkiezingen/vraag-en-antwoord/welke-verkiezingen-zijn-er"},{"sec":"knm","t":"Holidays","q":"Wat gebeurt er op Prinsjesdag, de derde dinsdag van september?","o":["De nieuwe Tweede Kamer wordt gekozen.","Nederland viert de bevrijding.","De koning leest de troonrede voor.","De koning viert zijn verjaardag."],"c":2,"en":"What happens on Prinsjesdag, the third Tuesday of September?","e":"On Prinsjesdag the King reads the troonrede with the government's plans, and the Minister of Finance presents the budget (Miljoenennota). Liberation is 5 May and the King's birthday is 27 April.","source":"https://www.rijksoverheid.nl/onderwerpen/prinsjesdag-traditie-en-ceremonie/vraag-en-antwoord/wat-is-prinsjesdag"},{"sec":"knm","t":"History","q":"Op 1 juli is Keti Koti. Wat herdenken en vieren mensen dan?","o":["Het einde van de Tweede Wereldoorlog","Het ontstaan van de Grondwet","De verjaardag van de koning","Het einde van de slavernij in 1863"],"c":3,"en":"On 1 July it is Keti Koti. What do people commemorate and celebrate then?","e":"Slavery was officially abolished on 1 July 1863 in Suriname and the Caribbean part of the Kingdom, and this is commemorated on 1 July. The end of WWII is remembered on 4 and 5 May.","source":"https://ninsee.nl/nationale-herdenking-slavernijverleden-dinsdag-1-juli-in-oosterpark-amsterdam/"},{"sec":"knm","t":"Holidays","q":"Koningsdag is op 27 april. Wat gebeurt er als 27 april op een zondag valt?","o":["Dan is Koningsdag op maandag 28 april.","Dan vieren we het een week later.","Dan is er dat jaar geen Koningsdag.","Dan is Koningsdag op zaterdag 26 april."],"c":3,"en":"King's Day is on 27 April. What happens if 27 April falls on a Sunday?","e":"If 27 April is a Sunday, King's Day is celebrated the day before, on Saturday 26 April. It does not move to Monday.","source":"https://www.koninklijkhuis.nl/onderwerpen/koningsdag"},{"sec":"knm","t":"History","q":"Wat vieren we in Nederland op 5 mei?","o":["De bevrijding in 1945","Het einde van de watersnood","De verjaardag van de koning","Het einde van de slavernij"],"c":0,"en":"What do we celebrate in the Netherlands on 5 May?","e":"On 5 May (Bevrijdingsdag) the Netherlands celebrates the liberation from German occupation in 1945. 4 May is the day of remembrance; 5 May is the celebration.","source":"https://www.4en5mei.nl/vieren/wat-vieren-we-op-5-mei"},{"sec":"knm","t":"History","q":"In 1953 was er een grote overstroming in Zeeland, Zuid-Holland en Noord-Brabant. Wat bouwde Nederland daarna?","o":["De Deltawerken","De Afsluitdijk","Het Centraal Station","De Zuiderzee"],"c":0,"en":"In 1953 there was a big flood in Zeeland, South Holland and North Brabant. What did the Netherlands build afterwards?","e":"After the 1953 flood (watersnoodramp), in which 1,836 people died, the Deltawerken were built to prevent a new disaster. The Afsluitdijk is older (1932).","source":"https://www.rijkswaterstaat.nl/water/waterbeheer/bescherming-tegen-het-water/watersnoodramp-1953"},{"sec":"knm","t":"History","q":"In 1919 nam het parlement een belangrijke wet aan voor vrouwen. Wat mochten vrouwen daarna?","o":["Studeren aan de universiteit","Stemmen bij verkiezingen","Een eigen winkel beginnen"],"c":1,"en":"In 1919 parliament passed an important law for women. What were women allowed to do after that?","e":"The 1919 law gave women the right to vote; they could vote from 1920 and first voted for the Tweede Kamer in 1922. Women could already study at university before that.","source":"https://www.parlement.com/vrouwenkiesrecht"},{"sec":"knm","t":"Society","q":"Wat gebeurde er in 2001 in Nederland, als eerste land ter wereld?","o":["Homo's en lesbiennes mochten trouwen.","Mannen en vrouwen kregen gelijk loon.","Vrouwen mochten voor het eerst stemmen.","De euro werd het nieuwe geld."],"c":0,"en":"What happened in the Netherlands in 2001, as the first country in the world?","e":"On 1 April 2001 the Netherlands was the first country in the world to open civil marriage to couples of the same sex. Women's suffrage dates from 1919.","source":"https://www.rijksoverheid.nl/actueel/nieuws/2025/09/05/het-eise-eisinga-planetarium-en-25-jaar-openstelling-van-het-huwelijk-themas-nieuwe-munten-2026"},{"sec":"knm","t":"Society","q":"Uw buurvrouw vertelt dat haar man haar slaat. Waar kan zij dag en nacht gratis hulp vragen?","o":["Bij de huurcommissie","Bij Veilig Thuis","Bij de Belastingdienst","Bij het UWV"],"c":1,"en":"Your neighbour tells you her husband hits her. Where can she get free help day and night?","e":"Veilig Thuis (0800-2000) is free, anonymous and open 24/7 for domestic violence and child abuse. In immediate danger, call 112.","source":"https://www.veiligthuis.nl/nl/contact"},{"sec":"knm","t":"Society","q":"Ali en Sara willen trouwen bij de gemeente en in de moskee. Wat is de regel?","o":["Eerst in de moskee, daarna bij de gemeente.","De volgorde maakt niet uit.","Alleen de moskee is ook genoeg.","Eerst bij de gemeente, daarna in de moskee."],"c":3,"en":"Ali and Sara want to marry at the municipality and in the mosque. What is the rule?","e":"A religious ceremony may only take place after the civil marriage at the gemeente. Only the civil marriage counts legally.","source":"https://www.rijksoverheid.nl/onderwerpen/trouwen-samenlevingscontract-en-geregistreerd-partnerschap/vraag-en-antwoord/trouwen-of-geregistreerd-partnerschap-sluiten"},{"sec":"knm","t":"Administration","q":"Uw baby is geboren. Binnen hoeveel dagen moet u de geboorte aangeven bij de gemeente?","o":["Binnen 3 dagen","Binnen 5 dagen","Binnen 2 weken","Binnen 1 maand"],"c":0,"en":"Your baby has been born. Within how many days must you register the birth at the municipality?","e":"A birth must be registered within 3 days, in the municipality where the child was born. 5 days is the rule for registering a move, a common mix-up.","source":"https://www.rijksoverheid.nl/onderwerpen/aangifte-geboorte-en-naamskeuze-kind/vraag-en-antwoord/aangifte-geboorte"},{"sec":"knm","t":"Administration","q":"Wanneer krijgt u een burgerservicenummer (BSN)?","o":["Bij het openen van een bankrekening","Bij het afsluiten van een zorgverzekering","Bij uw eerste werkdag","Bij inschrijving in de BRP"],"c":3,"en":"When do you get a citizen service number (BSN)?","e":"You get your BSN when you are registered in the Basisregistratie Personen (BRP) at the gemeente. Banks, employers and insurers ask for it, but they do not give it.","source":"https://www.rijksoverheid.nl/documenten/vraag-en-antwoord/privacy-en-persoonsgegevens/hoe-kom-ik-aan-een-burgerservicenummer-bsn"},{"sec":"knm","t":"Administration","q":"Uw neef wil uw toeslag online voor u regelen. Hij vraagt uw DigiD-code. Wat is goed?","o":["U machtigt hem via DigiD Machtigen.","U geeft hem uw DigiD-code.","U stuurt de code per e-mail.","U schrijft de code op een briefje."],"c":0,"en":"Your cousin wants to arrange your benefit online for you. He asks for your DigiD code. What is correct?","e":"Never give your DigiD login or PIN to anyone, even family. If someone else must arrange things for you, use DigiD Machtigen (authorisation).","source":"https://www.digid.nl/en/security/tips-secure-login"},{"sec":"knm","t":"Administration","q":"U moet aangifte inkomstenbelasting doen. Vóór welke datum moet die vaak binnen zijn?","o":["1 januari","1 april","1 mei","1 juli"],"c":2,"en":"You must file an income tax return. Before which date must it usually be received?","e":"The return must be in before the date in your letter from the Belastingdienst, which is often 1 May. 1 July is the usual date for rent increases, not tax.","source":"https://www.belastingdienst.nl/wps/wcm/connect/nl/belastingaangifte/content/wanneer-moet-ik-aangifte-doen"},{"sec":"knm","t":"Administration","q":"Vanaf welke leeftijd moet u een identiteitsbewijs kunnen laten zien als de politie daarom vraagt?","o":["Vanaf 12 jaar","Vanaf 16 jaar","Vanaf 14 jaar","Vanaf 18 jaar"],"c":2,"en":"From what age must you be able to show an ID if the police ask for it?","e":"The general identification duty starts at 14. Only for some public transport checks does it start at 12.","source":"https://www.rijksoverheid.nl/onderwerpen/identificatieplicht/vraag-en-antwoord/geldt-de-identificatieplicht-ook-voor-minderjarigen"},{"sec":"knm","t":"Administration","q":"Waar dient u uw aanvraag in om Nederlander te worden (naturalisatie)?","o":["Direct bij de IND","Bij de gemeente","Bij de politie","Bij DUO"],"c":1,"en":"Where do you submit your application to become Dutch (naturalisation)?","e":"You submit the naturalisation application at your gemeente, which checks it with you; the IND then decides. You normally need 5 years of residence and a passed inburgeringsexamen.","source":"https://ind.nl/en/dutch-citizenship/becoming-a-dutch-national-through-naturalisation"},{"sec":"knm","t":"Administration","q":"U krijgt zorgtoeslag. U gaat meer verdienen. Wat moet u doen?","o":["Niets, de Belastingdienst ziet het zelf.","De wijziging binnen 4 weken doorgeven.","Het pas aan het eind van het jaar melden.","Uw toeslag stopzetten bij de gemeente."],"c":1,"en":"You receive healthcare allowance (zorgtoeslag). You start earning more. What must you do?","e":"Changes that affect your allowance, such as income, must be reported within 4 weeks via Mijn toeslagen. If you wait, you may have to pay money back later.","source":"https://www.belastingdienst.nl/wps/wcm/connect/bldcontentnl/belastingdienst/prive/toeslagen/wijzigingen_doorgeven/wijzigingen_doorgeven"},{"sec":"a2-lezen","t":"Reading","p":"Beste bewoner,\nOp dinsdag 14 maart komt de monteur uw cv-ketel controleren. Hij komt tussen 8.00 en 12.00 uur. Wilt u thuis zijn? Kunt u die dag niet? Bel dan vóór vrijdag 10 maart naar 010-2345678. Dan maken we een nieuwe afspraak.\nMet vriendelijke groet,\nWoonstichting De Haven","q":"Wanneer komt de monteur?","o":["Vrijdag 10 maart, 's ochtends","Vrijdag 10 maart, 's middags","Dinsdag 14 maart, 's middags","Dinsdag 14 maart, 's ochtends"],"c":3,"en":"When does the technician come?","e":"He comes on Tuesday 14 March between 8.00 and 12.00, so in the morning. Friday 10 March is the deadline to call, not the visit."},{"sec":"a2-lezen","t":"Reading","p":"Beste bewoner,\nOp dinsdag 14 maart komt de monteur uw cv-ketel controleren. Hij komt tussen 8.00 en 12.00 uur. Wilt u thuis zijn? Kunt u die dag niet? Bel dan vóór vrijdag 10 maart naar 010-2345678. Dan maken we een nieuwe afspraak.\nMet vriendelijke groet,\nWoonstichting De Haven","q":"U bent op 14 maart niet thuis. Wat moet u doen?","o":["Op 14 maart de monteur bellen","Een briefje op de deur hangen","Vóór 10 maart de woonstichting bellen","Niets, de monteur komt later terug"],"c":2,"en":"You are not home on 14 March. What must you do?","e":"The letter says to call before Friday 10 March to make a new appointment. Calling on the day itself is too late."},{"sec":"a2-lezen","t":"Reading","p":"Beste ouders,\nOp donderdag 22 mei gaat groep 5 op schoolreis naar de dierentuin. De kinderen moeten om 8.15 uur op school zijn. De bus vertrekt om 8.30 uur. We zijn om ongeveer 16.00 uur terug. Geef uw kind een lunchpakket mee. Drinken krijgen de kinderen van school.\nJuf Anouk","q":"Hoe laat moeten de kinderen op school zijn?","o":["Om 8.00 uur","Om 16.00 uur","Om 8.30 uur","Om 8.15 uur"],"c":3,"en":"What time must the children be at school?","e":"Children must be at school at 8.15. 8.30 is when the bus leaves, which is the trap."},{"sec":"a2-lezen","t":"Reading","p":"Beste ouders,\nOp donderdag 22 mei gaat groep 5 op schoolreis naar de dierentuin. De kinderen moeten om 8.15 uur op school zijn. De bus vertrekt om 8.30 uur. We zijn om ongeveer 16.00 uur terug. Geef uw kind een lunchpakket mee. Drinken krijgen de kinderen van school.\nJuf Anouk","q":"Wat moeten de kinderen zelf meenemen?","o":["Drinken","Geld voor de bus","Een lunchpakket","Niets"],"c":2,"en":"What must the children bring themselves?","e":"Parents must give a packed lunch. Drinks are provided by the school, so you don't need to bring them."},{"sec":"a2-lezen","t":"Reading","p":"Let op!\nDe lift is buiten gebruik van maandag 3 juni tot en met woensdag 5 juni. Er komt een nieuwe motor in. Gebruik de trap. Heeft u een rolstoel of rollator? Bel dan de huismeester: 06-12345678. Hij helpt u graag.\nDe huismeester","q":"Hoeveel dagen kunt u de lift niet gebruiken?","o":["3 dagen","2 dagen","1 dag","5 dagen"],"c":0,"en":"For how many days can you not use the lift?","e":"Monday 3 June up to and including (tot en met) Wednesday 5 June is 3 days. '5' is the date, not the number of days."},{"sec":"a2-lezen","t":"Reading","p":"Let op!\nDe lift is buiten gebruik van maandag 3 juni tot en met woensdag 5 juni. Er komt een nieuwe motor in. Gebruik de trap. Heeft u een rolstoel of rollator? Bel dan de huismeester: 06-12345678. Hij helpt u graag.\nDe huismeester","q":"Mevrouw Jansen loopt met een rollator. Wat kan zij doen?","o":["De huismeester bellen","Toch de lift nemen","De monteur om hulp vragen","Een nieuwe motor bestellen"],"c":0,"en":"Mrs Jansen walks with a rollator. What can she do?","e":"People with a wheelchair or rollator should call the huismeester, who will help. The lift cannot be used at all during those days."},{"sec":"a2-lezen","t":"Reading","p":"Sportschool FitFit, openingstijden\nMaandag tot en met vrijdag: van 7.00 tot 22.00 uur\nZaterdag: van 9.00 tot 17.00 uur\nZondag: gesloten\nOp feestdagen zijn we open van 10.00 tot 14.00 uur, behalve op 1e Kerstdag en Nieuwjaarsdag. Dan zijn we de hele dag dicht.","q":"Op Koningsdag (een feestdag) wilt u sporten. Wanneer kan dat?","o":["Van 10.00 tot 14.00 uur","Van 9.00 tot 17.00 uur","Van 7.00 tot 22.00 uur","Niet, de sportschool is dicht"],"c":0,"en":"On King's Day (a public holiday) you want to work out. When is that possible?","e":"On public holidays the gym is open from 10.00 to 14.00. Only Christmas Day and New Year's Day are the exceptions (behalve)."},{"sec":"a2-lezen","t":"Reading","p":"Sportschool FitFit, openingstijden\nMaandag tot en met vrijdag: van 7.00 tot 22.00 uur\nZaterdag: van 9.00 tot 17.00 uur\nZondag: gesloten\nOp feestdagen zijn we open van 10.00 tot 14.00 uur, behalve op 1e Kerstdag en Nieuwjaarsdag. Dan zijn we de hele dag dicht.","q":"Op welke dag is de sportschool de hele dag dicht?","o":["Op zaterdag","Op 1e Kerstdag","Op maandag","Op Koningsdag"],"c":1,"en":"On which day is the gym closed all day?","e":"The word 'behalve' (except) shows that on Christmas Day and New Year's Day the gym is closed all day. Sunday is also closed, but it is not an option here."},{"sec":"a2-lezen","t":"Reading","p":"Hoi Sara, ik ben ziek en ik heb koorts. Kun jij morgen mijn dienst doen? Het is van 14.00 tot 22.00 uur. Dan werk ik zaterdag voor jou. Laat je het vóór 18.00 uur weten? Dan bel ik de manager. Groetjes, Inge","q":"Wat vraagt Inge aan Sara?","o":["Of Sara de manager wil bellen","Of Sara morgen voor haar wil werken","Of Sara zaterdag vrij wil nemen","Of Sara medicijnen wil brengen"],"c":1,"en":"What does Inge ask Sara?","e":"Inge asks Sara to do her shift tomorrow. Inge will call the manager herself, so that is the trap."},{"sec":"a2-lezen","t":"Reading","p":"Hoi Sara, ik ben ziek en ik heb koorts. Kun jij morgen mijn dienst doen? Het is van 14.00 tot 22.00 uur. Dan werk ik zaterdag voor jou. Laat je het vóór 18.00 uur weten? Dan bel ik de manager. Groetjes, Inge","q":"Wanneer moet Sara antwoorden?","o":["Vóór 14.00 uur","Vóór 18.00 uur","Vóór 22.00 uur","Op zaterdag"],"c":1,"en":"When must Sara reply?","e":"Inge asks for an answer before 18.00. 14.00 and 22.00 are the start and end of the shift."},{"sec":"a2-lezen","t":"Reading","p":"Geachte heer Benali,\nUw nieuwe paspoort is klaar. U kunt het ophalen op het stadhuis, tot 3 maanden na de datum van deze brief. Maak eerst een afspraak via onze website. Zonder afspraak kunt u niet langskomen. Neem uw oude paspoort mee.\nGemeente Zwolle","q":"Wat moet meneer Benali eerst doen?","o":["Een afspraak maken via de website","Naar het stadhuis gaan","Zijn oude paspoort opsturen","De gemeente een brief schrijven"],"c":0,"en":"What must Mr Benali do first?","e":"He must first make an appointment online; without one he cannot come. Going straight to the town hall is the trap."},{"sec":"a2-lezen","t":"Reading","p":"Geachte heer Benali,\nUw nieuwe paspoort is klaar. U kunt het ophalen op het stadhuis, tot 3 maanden na de datum van deze brief. Maak eerst een afspraak via onze website. Zonder afspraak kunt u niet langskomen. Neem uw oude paspoort mee.\nGemeente Zwolle","q":"Wat moet hij meenemen naar het stadhuis?","o":["Zijn huurcontract","Een nieuwe pasfoto","Zijn oude paspoort","Een bewijs van betaling"],"c":2,"en":"What must he bring to the town hall?","e":"The letter only says to bring his old passport. The other items are not mentioned."},{"sec":"a2-lezen","t":"Reading","p":"Te koop: kinderfiets\nRood, voor kinderen van 6 tot 9 jaar. De fiets is 2 jaar oud en heeft goede banden. Prijs: € 45. Ophalen in Utrecht-Oost, ik bezorg niet. Bellen na 18.00 uur: 06-98765432. Overdag ben ik aan het werk.\nGroet, Ruud","q":"Wanneer kunt u Ruud bellen?","o":["Overdag","Na 18.00 uur","Vóór 18.00 uur","De hele dag"],"c":1,"en":"When can you call Ruud?","e":"Ruud says to call after (na) 18.00 because he works during the day. 'Vóór' would be the opposite."},{"sec":"a2-lezen","t":"Reading","p":"Te koop: kinderfiets\nRood, voor kinderen van 6 tot 9 jaar. De fiets is 2 jaar oud en heeft goede banden. Prijs: € 45. Ophalen in Utrecht-Oost, ik bezorg niet. Bellen na 18.00 uur: 06-98765432. Overdag ben ik aan het werk.\nGroet, Ruud","q":"Wat is waar?","o":["U moet de fiets zelf ophalen.","Ruud brengt de fiets naar uw huis.","De fiets is helemaal nieuw.","De fiets is voor kinderen van 2 jaar."],"c":0,"en":"What is true?","e":"'Ophalen, ik bezorg niet' means you have to collect it yourself. '2 jaar' is the age of the bike, not of the child."},{"sec":"a2-lezen","t":"Reading","p":"Tandartspraktijk De Glimlach is gesloten van maandag 22 juli tot en met vrijdag 9 augustus. Heeft u in die tijd veel pijn of een ander probleem met spoed? Bel dan tandarts Visser: 030-1122334. Voor een gewone controle kunt u vanaf 12 augustus weer bij ons terecht.","q":"U heeft op 1 augustus erge kiespijn. Wat doet u?","o":["U wacht tot 12 augustus.","U belt 112.","U gaat naar De Glimlach.","U belt tandarts Visser."],"c":3,"en":"You have bad toothache on 1 August. What do you do?","e":"1 August falls in the closed period, and for pain or urgent problems you call tandarts Visser. Waiting until 12 August is only for normal check-ups."},{"sec":"a2-lezen","t":"Reading","p":"Cursus Nederlands A2\nStart: dinsdag 6 september\nTien lessen, elke dinsdagavond van 19.00 tot 21.00 uur\nPlaats: Bibliotheek Centrum, zaal 2\nPrijs: € 120, het boek zit in de prijs\nAanmelden kan tot 1 september via de website.","q":"Hoe lang duurt één les?","o":["1 uur","2 uur","1,5 uur","3 uur"],"c":1,"en":"How long does one lesson last?","e":"Each lesson is from 19.00 to 21.00, which is 2 hours. Don't confuse this with the number of lessons (10)."},{"sec":"a2-lezen","t":"Reading","p":"Cursus Nederlands A2\nStart: dinsdag 6 september\nTien lessen, elke dinsdagavond van 19.00 tot 21.00 uur\nPlaats: Bibliotheek Centrum, zaal 2\nPrijs: € 120, het boek zit in de prijs\nAanmelden kan tot 1 september via de website.","q":"Hoeveel moet u extra betalen voor het boek?","o":["Niets","€ 12","€ 20","€ 120"],"c":0,"en":"How much extra must you pay for the book?","e":"'Het boek zit in de prijs' means the book is included in the €120, so you pay nothing extra."},{"sec":"a2-lezen","t":"Reading","p":"Beste buren,\nOp zaterdag 12 juli vier ik mijn 30e verjaardag. Er is muziek in de tuin. Het kan dus wat lawaai zijn, tot ongeveer 1 uur 's nachts. Sorry daarvoor! U bent ook van harte welkom, vanaf 20.00 uur. Neem gerust iets lekkers mee, maar het hoeft niet.\nGroeten, Daan (nummer 8)","q":"Waarom schrijft Daan deze brief?","o":["Hij vertelt over zijn feest.","Hij klaagt over lawaai van de buren.","Hij zoekt hulp in de tuin.","Hij gaat binnenkort verhuizen."],"c":0,"en":"Why does Daan write this letter?","e":"Daan tells his neighbours about his birthday party and warns about noise. He is not complaining about others."},{"sec":"a2-lezen","t":"Reading","p":"Beste buren,\nOp zaterdag 12 juli vier ik mijn 30e verjaardag. Er is muziek in de tuin. Het kan dus wat lawaai zijn, tot ongeveer 1 uur 's nachts. Sorry daarvoor! U bent ook van harte welkom, vanaf 20.00 uur. Neem gerust iets lekkers mee, maar het hoeft niet.\nGroeten, Daan (nummer 8)","q":"Wat moeten de buren meenemen?","o":["Muziek","Iets lekkers","Een cadeau","Niets, het hoeft niet"],"c":3,"en":"What must the neighbours bring?","e":"Daan says they may bring something tasty, 'maar het hoeft niet' (but it is not necessary). So they don't have to bring anything."},{"sec":"a2-lezen","t":"Reading","p":"Reizigersinformatie\nVan maandag 4 november tot en met zondag 17 november rijdt bus 12 niet langs het Centraal Station. Er wordt aan de weg gewerkt. U kunt in- en uitstappen bij de halte Marktplein. Die halte is 5 minuten lopen van het station.","q":"Hoe lang rijdt bus 12 niet langs het station?","o":["1 week","17 dagen","4 dagen","2 weken"],"c":3,"en":"For how long does bus 12 not go past the station?","e":"Monday 4 November up to and including Sunday 17 November is 14 days, so 2 weeks. 4 and 17 are dates, not durations."},{"sec":"a2-lezen","t":"Reading","p":"Reizigersinformatie\nVan maandag 4 november tot en met zondag 17 november rijdt bus 12 niet langs het Centraal Station. Er wordt aan de weg gewerkt. U kunt in- en uitstappen bij de halte Marktplein. Die halte is 5 minuten lopen van het station.","q":"Waar stapt u in deze periode in?","o":["Bij het Centraal Station","Bij de halte Marktplein","Bij een andere buslijn","Bij halte nummer 12"],"c":1,"en":"Where do you get on during this period?","e":"During the roadworks you get on and off at the Marktplein stop, a 5-minute walk from the station."},{"sec":"a2-lezen","t":"Reading","p":"Beste collega's,\nVanaf 1 maart verandert onze werktijd. We beginnen om 8.30 uur in plaats van 9.00 uur. De lunchpauze blijft een half uur. Op vrijdag stoppen we niet om 17.00 uur, maar al om 15.00 uur. Vragen? Kom even langs.\nGroet, Petra (HR)","q":"Hoe laat begint het werk vanaf 1 maart?","o":["Om 8.00 uur","Om 9.00 uur","Om 8.30 uur","Om 9.30 uur"],"c":2,"en":"What time does work start from 1 March?","e":"Work starts at 8.30 'in plaats van' (instead of) 9.00. 9.00 is the old time."},{"sec":"a2-lezen","t":"Reading","p":"Beste collega's,\nVanaf 1 maart verandert onze werktijd. We beginnen om 8.30 uur in plaats van 9.00 uur. De lunchpauze blijft een half uur. Op vrijdag stoppen we niet om 17.00 uur, maar al om 15.00 uur. Vragen? Kom even langs.\nGroet, Petra (HR)","q":"Wat verandert er op vrijdag?","o":["De lunchpauze wordt langer.","Het werk stopt om 17.00 uur.","Het werk stopt om 15.00 uur.","Er wordt niet meer gewerkt."],"c":2,"en":"What changes on Friday?","e":"'Niet om 17.00 uur, maar al om 15.00 uur': work now stops at 15.00. The lunch break stays the same."},{"sec":"a2-lezen","t":"Reading","p":"Beste klant,\nWilt u de standen van uw gas- en stroommeter aan ons doorgeven? Dat kan tot en met 15 januari, via de app of op onze website. Doet u dit niet? Dan schatten wij uw verbruik. Uw jaarnota kan dan hoger zijn.\nEnergiebedrijf Groenstroom","q":"Wat vraagt het energiebedrijf aan de klant?","o":["Een nieuwe meter kopen","Het energiebedrijf bellen","De jaarnota meteen betalen","De meterstanden doorgeven"],"c":3,"en":"What does the energy company ask the customer?","e":"The customer must pass on the gas and electricity meter readings via the app or website, by 15 January."},{"sec":"a2-lezen","t":"Reading","p":"Beste klant,\nWilt u de standen van uw gas- en stroommeter aan ons doorgeven? Dat kan tot en met 15 januari, via de app of op onze website. Doet u dit niet? Dan schatten wij uw verbruik. Uw jaarnota kan dan hoger zijn.\nEnergiebedrijf Groenstroom","q":"Wat gebeurt er als u niets doet?","o":["U krijgt een boete van de gemeente.","Uw gas en stroom gaan uit.","Het bedrijf schat uw verbruik.","U krijgt geld terug."],"c":2,"en":"What happens if you do nothing?","e":"If you don't pass on the readings, the company estimates (schat) your usage, and your annual bill may be higher. There is no fine or disconnection."},{"sec":"a2-luisteren","t":"Listening","audio":"Goedemiddag, met de tandartspraktijk. Uw afspraak van woensdag is verplaatst naar donderdag, om kwart voor elf. Kunt u dan niet? Bel ons dan terug.","q":"Wanneer is de nieuwe afspraak?","o":["Woensdag om 10.45 uur","Woensdag om 11.15 uur","Donderdag om 11.15 uur","Donderdag om 10.45 uur"],"c":3,"en":"When is the new appointment?","e":"The appointment moved from Wednesday to Thursday, and 'kwart voor elf' is 10.45. 11.15 would be 'kwart over elf'."},{"sec":"a2-luisteren","t":"Listening","audio":"Beste reizigers, bus 40 naar het ziekenhuis heeft vandaag ongeveer twintig minuten vertraging. Onze excuses.","q":"Wat is er met bus 40?","o":["Hij rijdt vandaag niet.","Hij is twintig minuten te laat.","Hij vertrekt twintig minuten eerder.","Hij rijdt niet naar het ziekenhuis."],"c":1,"en":"What is the matter with bus 40?","e":"'Vertraging' means delay: the bus is about twenty minutes late. It still runs to the hospital."},{"sec":"a2-luisteren","t":"Listening","audio":"Welkom bij Energiebedrijf Groenstroom. Heeft u een vraag over uw rekening? Toets 1. Wilt u een verhuizing doorgeven? Toets 2. Heeft u een storing? Toets 3.","q":"U gaat verhuizen. Welke toets kiest u?","o":["Toets 2","Toets 1","Toets 3","Geen toets, u wacht"],"c":0,"en":"You are moving house. Which key do you press?","e":"'Een verhuizing doorgeven' (report a move) is key 2. Key 1 is for questions about your bill, key 3 for an outage."},{"sec":"a2-luisteren","t":"Listening","audio":"Hoi, met Pieter. Even over het feest van zaterdag: het begint niet om acht uur, maar om half negen. Tot dan!","q":"Hoe laat begint het feest?","o":["20.00 uur","20.30 uur","21.30 uur","19.30 uur"],"c":1,"en":"What time does the party start?","e":"'Niet om acht uur, maar om half negen': 'half negen' means half an hour before nine, so 20.30. It is not 21.30."},{"sec":"a2-luisteren","t":"Listening","audio":"Beste klanten, over een kwartier sluit de winkel. Wilt u uw boodschappen naar de kassa brengen? Dank u wel.","q":"Wanneer gaat de winkel dicht?","o":["Over 15 minuten","Over 5 minuten","Over 30 minuten","Over een uur"],"c":0,"en":"When does the shop close?","e":"'Een kwartier' is 15 minutes. Don't confuse it with half an hour (een half uur)."},{"sec":"a2-luisteren","t":"Listening","audio":"Beste ouders, morgen begint de school later, om tien voor half tien. De leraren hebben eerst een vergadering.","q":"Hoe laat begint de school morgen?","o":["9.20 uur","9.40 uur","8.50 uur","10.20 uur"],"c":0,"en":"What time does school start tomorrow?","e":"'Tien voor half tien' is ten minutes before 9.30, so 9.20. 9.40 would be 'tien over half tien'."},{"sec":"a2-luisteren","t":"Listening","audio":"De kaartjes voor het museum kosten veertien euro. Voor kinderen tot twaalf jaar kost een kaartje zeven euro.","q":"Hoeveel kost een kaartje voor een volwassene?","o":["€ 7","€ 14","€ 12","€ 40"],"c":1,"en":"How much is a ticket for an adult?","e":"Adults pay 'veertien' (14) euro. 'Veertig' would be 40; €7 is the children's price and 12 is the age limit."},{"sec":"a2-luisteren","t":"Listening","audio":"Mevrouw, u neemt deze tabletten drie keer per dag, na het eten. Neem ze niet met melk, maar met water.","q":"Hoe neemt mevrouw de tabletten?","o":["Drie keer per dag, vóór het eten","Twee keer per dag, met melk","Drie keer per dag, met water","Eén keer per dag, na het eten"],"c":2,"en":"How does the woman take the tablets?","e":"Three times a day, after food, and 'niet met melk, maar met water'. The 'niet ... maar ...' construction is the trap."},{"sec":"a2-luisteren","t":"Listening","audio":"Goedemorgen, met Woonstichting De Haven. De monteur komt niet op maandag, maar op dinsdagochtend, tussen acht en twaalf uur.","q":"Wanneer komt de monteur?","o":["Maandagochtend","Maandagmiddag","Dinsdagochtend","Dinsdagmiddag"],"c":2,"en":"When does the technician come?","e":"'Niet op maandag, maar op dinsdagochtend': he comes Tuesday morning between 8 and 12."},{"sec":"a2-luisteren","t":"Listening","audio":"Hallo, met Karin van de yogaschool. De les van donderdag gaat niet door, want de docent is ziek. De volgende les is gewoon volgende week donderdag.","q":"Wat hoort u?","o":["De les is deze week op vrijdag.","Er komt een nieuwe docent.","De docent stopt met lesgeven.","Er is deze donderdag geen les."],"c":3,"en":"What do you hear?","e":"'Gaat niet door' means the lesson is cancelled this Thursday. Lessons continue as normal next week."},{"sec":"a2-luisteren","t":"Listening","audio":"Je kunt me bellen op nul zes, achtenveertig, negentien, zevenentwintig, drieëndertig.","q":"Wat is het telefoonnummer?","o":["06-84192733","06-48197233","06-48912733","06-48192733"],"c":3,"en":"What is the phone number?","e":"Achtenveertig = 48, negentien = 19, zevenentwintig = 27, drieëndertig = 33. In Dutch you say the last digit first: 'acht-en-veertig' is 48, not 84."},{"sec":"a2-luisteren","t":"Listening","audio":"Ik woon op de Lindelaan, nummer vierenzestig. Het is een blauw huis naast de bakker.","q":"Op welk nummer woont de spreker?","o":["64","46","74","60"],"c":0,"en":"At which number does the speaker live?","e":"'Vierenzestig' is four-and-sixty, so 64. Learners often write 46 because the 4 is said first."},{"sec":"a2-luisteren","t":"Listening","audio":"Hoi Ahmed, met Linda. Je dienst morgen is van zeven tot drie. Vergeet je pasje niet!","q":"Tot hoe laat werkt Ahmed morgen?","o":["Tot 13.00 uur","Tot 15.00 uur","Tot 17.00 uur","Tot 19.00 uur"],"c":1,"en":"Until what time does Ahmed work tomorrow?","e":"'Van zeven tot drie' is a day shift from 7.00 to 15.00. 'Drie' here means three in the afternoon."},{"sec":"a2-luisteren","t":"Listening","audio":"Welkom in het ziekenhuis. Het bezoekuur is 's middags van half drie tot vier uur, en 's avonds van zeven tot acht uur.","q":"Hoe laat begint het bezoekuur in de middag?","o":["14.00 uur","15.30 uur","14.30 uur","16.00 uur"],"c":2,"en":"What time does afternoon visiting start?","e":"'Half drie' is half an hour before three, so 14.30. 15.30 is a common mistake."},{"sec":"a2-luisteren","t":"Listening","audio":"Goedemiddag, met Fietsenmaker Bakker. Uw fiets is klaar. U kunt hem vandaag ophalen tot zes uur. De reparatie kost vijfendertig euro.","q":"Hoeveel kost de reparatie?","o":["€ 25","€ 53","€ 35","€ 65"],"c":2,"en":"How much does the repair cost?","e":"'Vijfendertig' is five-and-thirty, so 35. Saying the 5 first can make you think of 53."},{"sec":"a2-schrijven","t":"Grammar","type":"type","q":"Vul in: Vorige week ___ wij een nieuwe bank. (kopen)","a":["kochten"],"en":"Fill in: Last week we ___ a new sofa. (to buy)","e":"Kopen is irregular: the past tense plural is 'kochten'. 'Kocht' is singular and 'kopen' is present tense."},{"sec":"a2-schrijven","t":"Grammar","type":"type","q":"Vul in: Mijn zus ___ in een ziekenhuis. (werken)","a":["werkt"],"en":"Fill in: My sister ___ in a hospital. (to work)","e":"With hij/zij/het (my sister = zij) you add -t to the stem: werk + t = werkt."},{"sec":"a2-schrijven","t":"Grammar","type":"type","q":"Vul in: Ik heb gisteren mijn moeder ___. (bellen)","a":["gebeld"],"en":"Fill in: Yesterday I ___ my mother. (to call)","e":"Perfect tense: ge + stem + d/t. The stem 'bel' ends in l (not in 't kofschip), so it gets -d: gebeld."},{"sec":"a2-schrijven","t":"Grammar","type":"type","q":"Vul in: Eén stoel, twee ___.","a":["stoelen"],"en":"Fill in: One chair, two ___.","e":"Most Dutch nouns form the plural with -en: stoel becomes stoelen."},{"sec":"a2-schrijven","t":"Grammar","type":"type","q":"Vul in: Hij ___ elke dag om 7 uur op. (opstaan)","a":["staat"],"en":"Fill in: He ___ up every day at 7. (to get up)","e":"Opstaan is a separable verb: the verb part 'staat' goes in second position and 'op' goes to the end."},{"sec":"a2-schrijven","t":"Grammar","q":"Welke zin is goed?","o":["Vandaag werk ik thuis.","Vandaag ik werk thuis.","Vandaag thuis ik werk.","Werk vandaag ik thuis."],"c":0,"en":"Which sentence is correct?","e":"In a main clause the verb is always in second place. If the sentence starts with 'Vandaag', the subject comes after the verb: werk ik."},{"sec":"a2-schrijven","t":"Grammar","q":"Maak de zin af: Ik denk dat ...","o":["de winkel is morgen open.","de winkel morgen open is.","is de winkel morgen open.","de winkel open morgen is."],"c":1,"en":"Complete the sentence: I think that ...","e":"After 'dat' the verb goes to the end of the sentence: 'dat de winkel morgen open is'."},{"sec":"a2-schrijven","t":"Grammar","q":"Welke zin is goed?","o":["Als het regent, ik neem de bus.","Als regent het, neem ik de bus.","Als het regent, neem ik de bus.","Als het regent, de bus neem ik."],"c":2,"en":"Which sentence is correct?","e":"In the 'als' part the verb goes last (als het regent). The whole 'als' part counts as position one, so the main verb follows directly: neem ik."},{"sec":"a2-schrijven","t":"Writing","q":"U schrijft een e-mail aan de gemeente. Hoe sluit u de e-mail af?","o":["Doei!","Tot snel, xx","Liefs,","Met vriendelijke groet,"],"c":3,"en":"You write an email to the municipality. How do you end the email?","e":"In a formal email you close with 'Met vriendelijke groet,' and your name. 'Doei', 'Liefs' and 'xx' are only for friends and family."},{"sec":"a2-schrijven","t":"Grammar","q":"Welke zin is goed?","o":["Ik heb geen tijd.","Ik heb niet tijd.","Ik heb geen niet tijd.","Ik niet heb tijd."],"c":0,"en":"Which sentence is correct?","e":"You use 'geen' to make a noun without 'de/het' negative: geen tijd. 'Niet' is used with verbs, adjectives and specific things."}]};
