var GLOSSARY = {
  voorrangRechts:{label:"Voorrang van rechts (priority to the right)",def:"The default right-of-way rule in the Netherlands: at a junction with no signs or markings, you give way to traffic approaching from your right.",icon:GICONS.priorityRight},
  giveWay:{label:"Give way",def:"British English for what you may know as 'yield': let other traffic go first and only proceed once it's clear.",icon:signSvg("give-way")},
  builtUpArea:{label:"Built-up area (bebouwde kom)",def:"A town or village zone, marked by a white sign with a skyline icon at the entrance. Default speed limit inside is 50 km/h unless signed otherwise, even on streets that feel residential.",icon:GICONS.builtUpArea},
  roundabout:{label:"Roundabout",def:"A circular junction where traffic flows one-way around a central island. Whether circulating or entering traffic has priority depends on the signs and whether you're inside or outside a built-up area, so always check.",icon:GICONS.roundabout},
  roadLine:{label:"Solid vs broken road line",def:"A solid line down the middle of the road means you may not cross it to overtake or turn. A broken (dashed) line means crossing is allowed when safe.",icon:GICONS.roadMarkings},
  hazardLights:{label:"Hazard lights",def:"All indicator lights flashing together, used to warn others of sudden danger or an obstruction, such as a breakdown, not for routine parking.",icon:GICONS.hazardLights},
  hardShoulder:{label:"Hard shoulder",def:"The paved strip on the outer edge of a motorway, reserved for emergencies and breakdowns, not for driving or overtaking.",icon:GICONS.hardShoulder},
  perMille:{label:"Per mille (‰)",def:"A unit for blood alcohol concentration, one-tenth of a percent. The Dutch limit is 0.5‰ for experienced drivers and a stricter 0.2‰ for novice drivers.",icon:GICONS.perMille},
  noviceDriver:{label:"Novice driver",def:"Anyone in their first 5 years of holding a licence. Novice drivers face the stricter 0.2 per mille alcohol limit instead of the standard 0.5.",icon:GICONS.noviceDriver},
  zipMerging:{label:"Zip merging (ritsen)",def:"The Dutch-encouraged merging technique: use both lanes fully up to the merge point, then alternate one vehicle from each lane, like a zipper, instead of merging early.",icon:GICONS.zipMerging},
  beams:{label:"High beam / low beam",def:"High beam (full beam) lights the road far ahead but dazzles oncoming drivers. Low beam (dipped headlights) is what you must switch to whenever another vehicle approaches.",icon:GICONS.beams},
  railwayCrossing:{label:"Railway crossing",def:"A point where a road crosses train tracks at the same level, usually with barriers and red flashing lights. Stop completely once the lights start flashing, even if no train is visible yet.",icon:GICONS.railwayCrossing},
  zebraCrossing:{label:"Zebra crossing",def:"A pedestrian crossing marked with bold black-and-white stripes. You must give way to pedestrians on it or clearly about to step onto it.",icon:GICONS.zebraCrossing},
  sharksTeeth:{label:"Shark's teeth markings",def:"A row of white triangles painted across your lane before a junction, meaning you must give way to the road you're joining, often overriding the usual priority-from-the-right rule.",icon:GICONS.sharksTeeth},
  flashingBeacon:{label:"Flashing orange beacon",def:"An amber light on a vehicle's roof. It warns others the vehicle is slow-moving, oversized, or needs extra caution. It does not give the vehicle priority.",icon:GICONS.flashingBeacon},
  bestemmingsverkeer:{label:"Bestemmingsverkeer (destination traffic)",def:"Dutch for 'destination traffic'. A sign reading 'uitgezonderd bestemmingsverkeer' bans through-traffic, but vehicles that genuinely need to be there (residents, deliveries, visitors) are allowed in.",icon:GICONS.pedestrianZone},
  priorityRoad:{label:"Priority road (voorrangsweg)",def:"A road marked with a yellow diamond sign. Traffic joining from side roads must give way to you, until a matching end-of-priority sign cancels it.",icon:signSvg("priority-road")},
  noParking:{label:"No parking",def:"You may not leave your vehicle unattended here, but you may still stop briefly, for example to drop someone off.",icon:signSvg("no-parking")},
  noStopping:{label:"No stopping",def:"Stricter than 'no parking': you may not stop your vehicle here at all, not even briefly, except in a genuine emergency.",icon:GICONS.hazardLights}
};

var GLOSSARY_PATTERNS = [
  ["flashing orange beacon","flashingBeacon"],["voorrang van rechts","voorrangRechts"],
  ["shark(?:'|’)s teeth","sharksTeeth"],["railway crossing","railwayCrossing"],
  ["zebra crossing","zebraCrossing"],["bestemmingsverkeer","bestemmingsverkeer"],
  ["built-up area","builtUpArea"],["novice drivers?","noviceDriver"],["priority road","priorityRoad"],
  ["hazard lights","hazardLights"],["hard shoulder","hardShoulder"],["zip merging","zipMerging"],
  ["no stopping","noStopping"],["no parking","noParking"],["per mille","perMille"],
  ["broken line","roadLine"],["solid line","roadLine"],["roundabout","roundabout"],
  ["give way","giveWay"],["high beams?","beams"],["low beams?","beams"],["ritsen","zipMerging"]
];
var GLOSSARY_RE = new RegExp("\\b(" + GLOSSARY_PATTERNS.map(function(p){ return p[0]; }).join("|") + ")\\b", "gi");
function keyForMatch(text){
  for (var i = 0; i < GLOSSARY_PATTERNS.length; i++){
    if (new RegExp("^" + GLOSSARY_PATTERNS[i][0] + "$", "i").test(text)) return GLOSSARY_PATTERNS[i][1];
  }
  return null;
}
function markGlossary(text){
  return escapeHtml(text).replace(GLOSSARY_RE, function(m){
    var key = keyForMatch(m);
    return key ? '<span class="term" tabindex="0" role="button" data-term="' + key + '">' + m + '</span>' : m;
  });
}


