    {p:P_BIB, q:"Op welke dag is de bibliotheek gesloten?", o:["Zondag","Maandag","Zaterdag","Vrijdag"], c:0, en:"Which day is it closed?", e:"gesloten = closed."},
    {p:P_AFVAL, q:"Wanneer zet je de container buiten?", o:["Woensdag vóór 7.30 uur","Dinsdag vóór 7.30 uur","Woensdag na 7.30 uur","Dinsdagavond laat"], c:0, en:"Rubbish letter. When do you put the bin out?", e:"Pickup moves to Wednesday; before 7.30."},
    {p:P_AFVAL, q:"Wat is er anders dan normaal?", o:["Ophalen een dag later","Ophalen een dag eerder","Een nieuwe container","Deze week geen ophaal"], c:0, en:"What's different from normal?", e:"'een dag later'."},
    {p:P_FATIMA, q:"Waarom kan Fatima niet komen?", o:["Haar zoon is ziek","Zij is zelf ziek","Zij moet werken","Haar man is ziek"], c:0, en:"Why can't Fatima come?", e:"'Mijn zoon is ziek'."},
    {p:P_FATIMA, q:"Wat stelt Fatima voor?", o:["Volgende week zaterdag","Morgen wat later","Volgende week zondag","Bij Fatima thuis"], c:0, en:"What does Fatima suggest?", e:"'volgende week ... Zaterdag kan ik wel'."},
    {p:P_VAC, q:"Wat is nodig voor deze baan?", o:["Nederlands spreken","Ervaring in een winkel","Een eigen rijbewijs","Een mbo-diploma"], c:0, en:"Job ad. What is required?", e:"'Ervaring is niet nodig, maar je moet wel Nederlands spreken.'"},
    {p:P_VAC, q:"Op welke dag moet je zeker kunnen werken?", o:["Zaterdag","Zondag","Maandag","Vrijdag"], c:0, en:"Which day must you be able to work?", e:"'iemand die ook op zaterdag kan werken'."},
    {p:P_MED, q:"Wanneer neem je het medicijn in?", o:["3x per dag, na het eten","3x per dag, voor het eten","1x per dag, na het eten","Alleen bij pijn"], c:0, en:"When do you take the medicine?", e:"'3 keer per dag, na het eten'."},
    {p:P_PARK, q:"Hoe vraag je een parkeervergunning aan?", o:["Via de website","Bij het loket","Per brief","Bij de politie"], c:0, en:"How do you apply for a parking permit?", e:"'online via de website van de gemeente'."},
    {p:P_ZWEM, q:"Wat moet je doen met je abonnement?", o:["Niets","Het opzeggen","Het zelf verlengen","Het zwembad bellen"], c:0, en:"Swimming pool notice. What do you need to do with your subscription?", e:"'U hoeft dus niets te doen.' It's extended automatically."},
    {p:P_ZWEM, q:"Hoe lang is het zwembad dicht?", o:["2 weken","4 dagen","1 week","4 weken"], c:0, en:"How long is the pool closed?", e:"'2 weken dicht'. The 4 is the date (4 March)."}
