    {p:P_REPAIR, q:"Wat is het doel van een repair café?", o:["Minder afval, meer contact","Geld voor de gemeente","Goedkoop spullen kopen","Werk voor vrijwilligers"], c:0, en:"What's the goal of a repair café?", e:"'minder afval en meer contact in de buurt'."},
    {p:P_REPAIR, q:"Wat moet je betalen?", o:["Niets, een gift mag","Een vast bedrag","Alleen onderdelen","Een abonnement"], c:0, en:"What do you pay?", e:"'gratis' + 'gift' (= donation)."}
